const e=[{id:"geo-1",chapter:"Geographie & Natur",title:"Landesüberblick & Regionen",facts:[["Vier Hauptinseln","Japan besteht aus den vier Hauptinseln Honshu, Hokkaido, Kyushu und Shikoku sowie über 6.800 kleineren Inseln entlang des Pazifiks."],["Acht Regionen","Traditionell wird Japan in acht Regionen gegliedert: Hokkaido, Tohoku, Kanto, Chubu, Kansai, Chugoku, Shikoku und Kyushu&Okinawa."],["Bevölkerung","Mit rund 124 Millionen Menschen zählt Japan zu den bevölkerungsreichsten Ländern der Welt und ist eine der größten Volkswirtschaften."],["Insellage","Die Insellage sorgte historisch für relative Isolation vom asiatischen Festland, was eigenständige kulturelle Entwicklungen begünstigte."]],quiz:[{q:"Wie viele Hauptinseln hat Japan?",o:["Vier","Zwei","Sechs"],c:0},{q:"Wie viele traditionelle Regionen werden Japan zugeordnet?",o:["Acht","Drei","Zwölf"],c:0},{q:"Welche Rolle spielte die Insellage historisch?",o:["Relative Isolation vom Festland","Ständige Landinvasionen","Keine Bedeutung"],c:0},{q:"Wie ist Japan bevölkerungsmäßig einzuordnen?",o:["Unter den bevölkerungsreichsten Ländern der Welt","Eines der bevölkerungsärmsten Länder","Nur mittelgroß ohne Bedeutung"],c:0}]},{id:"geo-2",chapter:"Geographie & Natur",title:"Klima & Jahreszeiten",facts:[["Vier Jahreszeiten","Japan reicht klimatisch von subarktisch (Hokkaido) bis subtropisch (Okinawa) und hat vier ausgeprägte Jahreszeiten."],["Regenzeit","Die Regenzeit (梅雨, tsuyu) dauert meist von Juni bis Juli und prägt den japanischen Frühsommer."],["Taifun-Saison","Im Spätsommer und Frühherbst ziehen regelmäßig Taifune über Japan hinweg, besonders über die südlichen und östlichen Küsten."],["Kirschblüte","Die Kirschblüte (桜, sakura) im Frühling ist ein kulturelles Großereignis — beim Hanami wird ihr Anblick gemeinsam gefeiert."]],quiz:[{q:"Wie heißt die japanische Regenzeit?",o:["tsuyu","natsu","fuyu"],c:0},{q:"Was ist Hanami?",o:["Das Betrachten der Kirschblüte","Ein Weinfest","Eine Teezeremonie"],c:0},{q:"Welche Klimazonen deckt Japan ab?",o:["Von subarktisch bis subtropisch","Nur gemäßigt","Nur tropisch"],c:0},{q:"Wann treten in Japan häufig Taifune auf?",o:["Spätsommer bis Frühherbst","Mitten im Winter","Nie"],c:0}]},{id:"geo-3",chapter:"Geographie & Natur",title:"Naturkatastrophen & Nationalparks",facts:[["Feuerring","Japan liegt auf dem Pazifischen Feuerring mit vielen aktiven Vulkanen, darunter der Fuji und der Sakurajima."],["Erdbebensicherheit","Wegen häufiger Erdbeben gelten in Japan strenge Bauvorschriften und gut ausgebaute Frühwarnsysteme."],["Tsunami-Gefahr","Küstenregionen sind tsunamigefährdet — das große Tōhoku-Erdbeben von 2011 löste einen verheerenden Tsunami aus."],["Nationalparks",'34 Nationalparks schützen vielfältige Landschaften, darunter die als "Japanische Alpen" bekannten Gebirgszüge.']],quiz:[{q:"Was ist der Sakurajima?",o:["Ein aktiver Vulkan","Ein Fluss","Ein Nationalpark ohne Vulkane"],c:0},{q:"Wofür ist Japan wegen seiner Lage besonders anfällig?",o:["Erdbeben und Tsunamis","Wüstenbildung","Dauerfrost"],c:0},{q:"Wann ereignete sich das große Tōhoku-Erdbeben?",o:["2011","1995","1985"],c:0},{q:"Was schützen Japans Nationalparks unter anderem?",o:["Landschaften wie die Japanischen Alpen","Nur Stadtgebiete","Ausschließlich Küstenstreifen"],c:0}]},{id:"geo-4",chapter:"Geographie & Natur",title:"Tierwelt Japans",facts:[["Schneeaffen",'Japanmakaken (Nihonzaru), oft "Schneeaffen" genannt, sind dafür bekannt, sich in kalten Wintermonaten in heißen Quellen (Onsen) aufzuwärmen — besonders im Jigokudani-Affenpark in Nagano zu beobachten.'],["Rotkronenkranich","Der Rotkronenkranich (Tanchō) gilt als Glücks- und Treuesymbol und ziert unter anderem das Logo der Fluggesellschaft Japan Airlines."],["Tanuki","Der Marderhund (Tanuki) spielt in der japanischen Folklore eine große Rolle und wird oft als possenhafte, gestaltwandelnde Figur dargestellt, häufig als Keramikfigur vor Geschäften."],["Endemische Arten","Aufgrund der Insellage besitzt Japan zahlreiche endemische Arten, die nirgendwo sonst vorkommen, etwa die Iriomote-Wildkatze auf einer kleinen Insel der Ryukyu-Kette."]],quiz:[{q:"Wofür sind japanische Schneeaffen (Nihonzaru) besonders bekannt?",o:["Baden in heißen Quellen im Winter","Wanderungen über weite Strecken","Leben ausschließlich im Wasser"],c:0},{q:"Wofür steht der Rotkronenkranich (Tanchō) symbolisch?",o:["Glück und Treue","Unglück","Reichtum ohne weitere Bedeutung"],c:0},{q:"Wie wird der Tanuki in der japanischen Folklore oft dargestellt?",o:["Als possenhafte, gestaltwandelnde Figur","Als gefährliches Raubtier","Als heiliger Vogel"],c:0},{q:"Was ist die Iriomote-Wildkatze?",o:["Eine endemische Art auf einer Ryukyu-Insel","Eine Haustierrasse","Ein ausgestorbenes Tier"],c:0}]},{id:"geo-5",chapter:"Geographie & Natur",title:"Inseln & Grenzgebiete",facts:[["Okinawa & Ryukyu-Inseln","Die subtropische Inselkette Okinawa hat eine eigene, historisch als Königreich Ryūkyū unabhängige Kultur mit eigener Sprache, Küche und Architektur."],["Hokkaido & Ainu","Die nördliche Insel Hokkaido ist die angestammte Heimat der indigenen Ainu, deren eigene Sprache und Kultur sich deutlich vom übrigen Japan unterscheiden."],["Ogasawara-Inseln",'Die abgelegenen Ogasawara-Inseln, wegen ihrer einzigartigen Tier- und Pflanzenwelt oft "Galapagos des Ostens" genannt, sind UNESCO-Weltnaturerbe und nur per Schiff erreichbar.'],["Umstrittene Inselgebiete","Japan hat mit mehreren Nachbarländern territoriale Streitigkeiten um kleine Inselgruppen, deren Zugehörigkeit unterschiedlich beansprucht wird."]],quiz:[{q:"Was war das historische Königreich auf den Ryukyu-Inseln?",o:["Königreich Ryūkyū","Kaiserreich Okinawa","Shogunat Naha"],c:0},{q:"Wer sind die indigenen Bewohner Hokkaidos?",o:["Die Ainu","Die Ryukyu","Die Yamato"],c:0},{q:'Warum werden die Ogasawara-Inseln oft "Galapagos des Ostens" genannt?',o:["Wegen ihrer einzigartigen Tier- und Pflanzenwelt","Wegen ihrer Vulkane","Wegen ihrer Nähe zu Südamerika"],c:0},{q:"Was betrifft mehrere territoriale Streitigkeiten Japans mit Nachbarländern?",o:["Kleine Inselgruppen","Die Hauptstadt Tokio","Den Fuji"],c:0}]},{id:"geo-6",chapter:"Geographie & Natur",title:"Gebirge, Vulkane & Wald",facts:[["Gebirgsland","Rund drei Viertel Japans sind gebirgig. Siedlungen, Landwirtschaft und Verkehr drängen sich in schmale Küstenebenen wie die Kantō-Ebene um Tokyo."],["Der Fuji","Mit 3.776 m ist der Fuji der höchste Berg Japans — ein aktiver Schichtvulkan, dessen letzter Ausbruch 1707 war. Er gilt als heilig und ist UNESCO-Welterbe."],["Kurze, reißende Flüsse","Japans Flüsse sind kurz, steil und schnell; sie neigen zu Hochwasser und sind kaum schiffbar. Der längste ist der Shinano mit etwa 367 km."],["Wald & heiße Quellen","Etwa zwei Drittel der Landesfläche sind bewaldet — einer der höchsten Werte unter den Industrieländern. Der Vulkanismus speist Tausende heiße Quellen (Onsen)."]],quiz:[{q:"Wie groß ist der gebirgige Anteil Japans ungefähr?",o:["Rund drei Viertel","Etwa ein Viertel","Ungefähr die Hälfte"],c:0},{q:"Was ist der Fuji geologisch?",o:["Ein aktiver Schichtvulkan","Ein seit der Eiszeit erloschener Vulkan","Ein reiner Faltenberg ohne Vulkanismus"],c:0},{q:"Was ist typisch für japanische Flüsse?",o:["Kurz, steil und reißend","Lang und ruhig schiffbar","Fast das ganze Jahr zugefroren"],c:0},{q:"Wie hoch ist der Waldanteil Japans etwa?",o:["Rund zwei Drittel der Landesfläche","Etwa ein Zehntel","Nahezu kein Wald"],c:0}]},{id:"hist-1",chapter:"Geschichte",title:"Jomon- und Yayoi-Zeit",facts:[["Jomon-Zeit","Die Jomon-Zeit (ca. 14.000–300 v. Chr.) war eine Jäger-und-Sammler-Kultur, bekannt für ihre charakteristische Schnurmuster-Keramik."],["Yayoi-Zeit","In der Yayoi-Zeit (ca. 300 v. Chr.–300 n. Chr.) kamen Nassreisanbau sowie Bronze- und Eisenverarbeitung vom Festland nach Japan."],["Soziale Hierarchien","Mit dem Reisanbau entstanden erste feste Siedlungsgemeinschaften und soziale Hierarchien."],["Frühe Reiche","Chinesische Quellen erwähnen bereits früh japanische Königreiche wie das legendäre Yamatai."]],quiz:[{q:"Wofür ist die Jomon-Zeit bekannt?",o:["Schnurmuster-Keramik","Buddhistische Tempel","Samurai-Kultur"],c:0},{q:"Was brachte die Yayoi-Zeit Neues?",o:["Nassreisanbau und Metallverarbeitung","Erste Automobile","Buchdruck"],c:0},{q:"Woher stammen frühe schriftliche Erwähnungen japanischer Reiche?",o:["Chinesische Quellen","Japanische Verfassung","Europäische Reiseberichte"],c:0},{q:"Wie alt ist die Jomon-Zeit ungefähr?",o:["Beginn vor über 10.000 Jahren","Beginn im 19. Jahrhundert","Beginn im Mittelalter"],c:0}]},{id:"hist-2",chapter:"Geschichte",title:"Kofun- und Asuka-Zeit",facts:[["Kofun","Die Kofun-Zeit ist nach den monumentalen Grabhügeln (kofun) benannt, die für Herrscher errichtet wurden — ein Zeichen zentraler Macht."],["Ankunft des Buddhismus","Im 6. Jahrhundert wurde der Buddhismus über Korea nach Japan eingeführt und veränderte Religion und Kunst nachhaltig."],["Shōtoku Taishi","Prinzregent Shōtoku Taishi förderte den Buddhismus und orientierte die Verwaltung am chinesischen Vorbild."],["Erste Gesetzeswerke","In dieser Zeit entstanden erste schriftliche Gesetzeswerke, stark an chinesischen Modellen orientiert."]],quiz:[{q:"Was sind kofun?",o:["Monumentale Grabhügel","Teehäuser","Handelsschiffe"],c:0},{q:"Wann kam der Buddhismus offiziell nach Japan?",o:["Im 6. Jahrhundert","Im 20. Jahrhundert","In der Steinzeit"],c:0},{q:"Wer förderte in der Asuka-Zeit den Buddhismus maßgeblich?",o:["Prinzregent Shōtoku Taishi","Kaiser Meiji","Tokugawa Ieyasu"],c:0},{q:"An welchem Vorbild orientierten sich frühe Verwaltungsreformen?",o:["Chinesisches Modell","Britisches Empire","Römisches Recht"],c:0}]},{id:"hist-3",chapter:"Geschichte",title:"Nara- und Heian-Zeit",facts:[["Nara-Zeit","Die Nara-Zeit (710–794) brachte mit Nara die erste dauerhafte Hauptstadt Japans und starken buddhistischen Tempelbau."],["Heian-Zeit","In der Heian-Zeit (794–1185) war Heian-kyō — das heutige Kyoto — Hauptstadt und Zentrum einer Blütezeit der Hofkultur."],["Hiragana & Katakana","Aus vereinfachten chinesischen Schriftzeichen entwickelten sich in dieser Zeit die Silbenschriften Hiragana und Katakana."],["Genji Monogatari",'"Die Geschichte vom Prinzen Genji" entstand in der Heian-Zeit und gilt oft als einer der ersten Romane der Weltliteratur.']],quiz:[{q:"Welche Stadt war die erste dauerhafte Hauptstadt Japans?",o:["Nara","Tokyo","Osaka"],c:0},{q:"Wie hieß die Hauptstadt der Heian-Zeit?",o:["Heian-kyō, heute Kyoto","Edo, heute Tokyo","Naniwa, heute Osaka"],c:0},{q:"Was entstand in dieser Zeit aus chinesischen Schriftzeichen?",o:["Hiragana und Katakana","Das lateinische Alphabet","Die Kanji selbst"],c:0},{q:"Welches berühmte Werk stammt aus der Heian-Zeit?",o:["Die Geschichte vom Prinzen Genji","Bushido: The Soul of Japan","Kojiki"],c:0}]},{id:"hist-4",chapter:"Geschichte",title:"Kamakura-Zeit",facts:[["Erstes Shogunat","1185 wurde Minamoto no Yoritomo erster Shogun — das Kamakura-Shogunat begann und verlagerte Macht an Kriegerführer."],["Aufstieg der Samurai","Die Samurai stiegen in dieser Zeit endgültig zur herrschenden Kriegerklasse Japans auf."],["Zen gewinnt an Bedeutung","Der Zen-Buddhismus gewann besonders unter den Samurai stark an Einfluss."],["Mongolische Invasionen",'Zwei mongolische Invasionsversuche (1274 und 1281) scheiterten unter anderem an Taifunen, die als "Kamikaze" (göttlicher Wind) bekannt wurden.']],quiz:[{q:"Wer wurde 1185 erster Shogun?",o:["Minamoto no Yoritomo","Tokugawa Ieyasu","Oda Nobunaga"],c:0},{q:"Welche Klasse stieg in der Kamakura-Zeit zur herrschenden Macht auf?",o:["Die Samurai","Die Bauern","Die Händler"],c:0},{q:'Was bedeutet der Begriff "Kamikaze" ursprünglich?',o:["Göttlicher Wind, der mongolische Invasionsflotten zerstörte","Ein Fluggerät","Ein Schwerttyp"],c:0},{q:"Welche Religion gewann bei den Samurai der Kamakura-Zeit an Bedeutung?",o:["Zen-Buddhismus","Christentum","Konfuzianismus"],c:0}]},{id:"hist-5",chapter:"Geschichte",title:"Muromachi- und Sengoku-Zeit",facts:[["Ashikaga-Shogunat","Die Muromachi-Zeit (1336–1573) stand unter dem Ashikaga-Shogunat und brachte die Blüte von Nō-Theater und Teezeremonie."],["Sengoku-Zeit",'Die "Zeit der streitenden Reiche" war geprägt von jahrzehntelangen Bürgerkriegen rivalisierender Daimyō (Fürsten).'],["Ankunft der Portugiesen","1543 brachten Portugiesen erstmals Feuerwaffen nach Japan, was die Kriegsführung veränderte."],["Christliche Mission","Missionare wie Francisco de Xavier begannen in dieser Zeit mit der christlichen Missionierung Japans."]],quiz:[{q:"Wie wird die Zeit der Bürgerkriege rivalisierender Fürsten genannt?",o:["Sengoku-Zeit","Heian-Zeit","Meiji-Zeit"],c:0},{q:"Was brachten die Portugiesen 1543 nach Japan?",o:["Feuerwaffen","Buddhismus","Reisanbau"],c:0},{q:"Welche Kunstform blühte in der Muromachi-Zeit auf?",o:["Nō-Theater","Kabuki","Anime"],c:0},{q:"Wer begann in dieser Zeit mit christlicher Missionierung in Japan?",o:["Francisco de Xavier","Marco Polo","Matthew Perry"],c:0}]},{id:"hist-6",chapter:"Geschichte",title:"Azuchi-Momoyama-Zeit",facts:[["Oda Nobunaga","Oda Nobunaga begann im 16. Jahrhundert die militärische Einigung des zersplitterten Japans."],["Toyotomi Hideyoshi",'Toyotomi Hideyoshi vollendete die Reichseinigung nach Nobunaga und ließ per "Schwertjagd" Bauern entwaffnen.'],["Prächtige Burgen","Monumentale Burgenbauten wie die Burg Osaka dienten als machtvolle Symbole der neuen Herrscher."],["Erste Spannungen","Gegen Ende dieser Zeit begannen sich erste Spannungen mit den christlichen Missionaren und Konvertiten anzukündigen."]],quiz:[{q:"Wer begann die militärische Einigung Japans im 16. Jahrhundert?",o:["Oda Nobunaga","Tokugawa Ieyasu","Minamoto no Yoritomo"],c:0},{q:"Wer vollendete die Reichseinigung nach Nobunaga?",o:["Toyotomi Hideyoshi","Kaiser Meiji","Shōtoku Taishi"],c:0},{q:'Was war die "Schwertjagd"?',o:["Entwaffnung der Bauern","Ein Fechtturnier","Ein Fischereigesetz"],c:0},{q:"Wofür steht diese Epoche architektonisch?",o:["Prächtige Burgenbauten","Erste Wolkenkratzer","Einfache Holzhütten ohne Verzierung"],c:0}]},{id:"hist-7",chapter:"Geschichte",title:"Edo-Zeit: Isolation & Gesellschaftsordnung",facts:[["Tokugawa-Shogunat","1603 gründete Tokugawa Ieyasu das Edo-Shogunat mit Hauptstadt Edo — dem heutigen Tokyo."],["Sakoku","Ab etwa 1639 schottete sich Japan durch die Sakoku-Politik weitgehend vom Ausland ab."],["Ständesystem","Ein striktes Ständesystem ordnete die Gesellschaft in Samurai, Bauern, Handwerker und Händler (shi-nō-kō-shō)."],["Pax Tokugawa",'Über 250 Jahre relativer innerer Frieden prägten die Edo-Zeit — bekannt als "Pax Tokugawa".']],quiz:[{q:"Wer gründete 1603 das Edo-Shogunat?",o:["Tokugawa Ieyasu","Oda Nobunaga","Matthew Perry"],c:0},{q:"Wie wird die Abschottungspolitik der Edo-Zeit genannt?",o:["Sakoku","Bushido","Sengoku"],c:0},{q:"Welches Ständesystem prägte die Gesellschaft?",o:["Samurai, Bauern, Handwerker, Händler","Nur Adel und Sklaven","Ein klassenloses System"],c:0},{q:"Wie lange dauerte die Edo-Zeit ungefähr?",o:["Über 250 Jahre","Nur 10 Jahre","Etwa 1000 Jahre"],c:0}]},{id:"hist-8",chapter:"Geschichte",title:"Edo-Zeit: Kultur & Wirtschaft",facts:[["Handelsstädte","Der Aufstieg großer Handelsstädte förderte die Entwicklung einer eigenständigen Geldwirtschaft."],["Ukiyo-e","Farbholzschnitte (Ukiyo-e) von Künstlern wie Hokusai und Hiroshige florierten als beliebte Massenkunst."],["Kabuki","Das dynamische Kabuki-Theater wurde zur populären Unterhaltung des aufstrebenden Bürgertums."],["Dejima","Trotz Isolation lief begrenzter Handel mit den Niederlanden über die künstliche Insel Dejima bei Nagasaki."]],quiz:[{q:"Was sind Ukiyo-e?",o:["Japanische Farbholzschnitte","Ein Schwerttyp","Eine Teesorte"],c:0},{q:"Über welche Insel lief begrenzter Handel mit den Niederlanden?",o:["Dejima","Okinawa","Sado"],c:0},{q:"Welche Theaterform wurde im Bürgertum der Edo-Zeit populär?",o:["Kabuki","Oper","Ballett"],c:0},{q:'Welcher Künstler schuf Ukiyo-e-Meisterwerke wie "Die große Welle"?',o:["Hokusai","Rembrandt","Michelangelo"],c:0}]},{id:"hist-9",chapter:"Geschichte",title:"Meiji-Restauration & Modernisierung",facts:[["Schwarze Schiffe",'1853/54 erzwang Commodore Matthew Perry mit seinen "Schwarzen Schiffen" die Öffnung Japans für den Westen.'],["Meiji-Restauration","1868 endete mit der Meiji-Restauration das Shogunat, der Kaiser wurde formal wieder zum Machtzentrum."],["Rasante Modernisierung","Japan industrialisierte in wenigen Jahrzehnten und übernahm westliche Verwaltungs- und Militärstrukturen."],["Erste Verfassung","1889 erhielt Japan eine moderne Verfassung und ein Parlament nach westlichem Vorbild."]],quiz:[{q:"Wer erzwang 1853/54 die Öffnung Japans?",o:["Commodore Matthew Perry","Marco Polo","Francisco de Xavier"],c:0},{q:"Was endete mit der Meiji-Restauration 1868?",o:["Das Shogunat","Der Buddhismus","Der Reisanbau"],c:0},{q:"Woran orientierte sich Japan bei der Modernisierung stark?",o:["An westlichen Verwaltungs- und Militärmodellen","An altägyptischen Vorbildern","An keinerlei Vorbildern"],c:0},{q:"Wann erhielt Japan seine erste moderne Verfassung?",o:["1889","1603","1945"],c:0}]},{id:"hist-10",chapter:"Geschichte",title:"20. Jahrhundert: Taishō, Shōwa & Wiederaufbau",facts:[["Taishō-Demokratie",'Die Taishō-Zeit (1912–1926) brachte eine kurze Phase liberalerer Politik, bekannt als "Taishō-Demokratie".'],["Krieg & Kapitulation","Die Shōwa-Zeit war von Militarisierung und dem Zweiten Weltkrieg geprägt, der 1945 mit den Atombombenabwürfen auf Hiroshima und Nagasaki endete."],["Nachkriegsverfassung","Die Verfassung von 1947 enthält mit Artikel 9 einen Verzicht auf Kriegsführung als Mittel der Außenpolitik."],["Wirtschaftswunder","Rasantes Wirtschaftswachstum machte Japan bis in die 1980er-Jahre zur zweitgrößten Volkswirtschaft der Welt."]],quiz:[{q:"Wie wird die kurze liberale Phase der 1910er/20er Jahre genannt?",o:["Taishō-Demokratie","Meiji-Reform","Heisei-Wandel"],c:0},{q:"Was regelt Artikel 9 der Nachkriegsverfassung?",o:["Verzicht auf Kriegsführung","Das Wahlrecht","Die Kaiserwürde"],c:0},{q:"Auf welche Städte fielen 1945 Atombomben?",o:["Hiroshima und Nagasaki","Tokyo und Osaka","Kyoto und Nara"],c:0},{q:"Was kennzeichnete die japanische Wirtschaft bis in die 1980er?",o:["Extrem schnelles Wachstum","Dauerhafte Rezession","Kompletter Stillstand"],c:0}]},{id:"rel-1",chapter:"Religion & Philosophie",title:"Shintō: Grundlagen",facts:[["Weg der Götter",'Shintō bedeutet wörtlich "Weg der Götter" — eine einheimische Naturreligion ohne zentrales Dogma oder Gründerfigur.'],["Kami","Kami sind Geister oder Gottheiten, die in Naturphänomenen, Orten und verehrten Ahnen wohnen können."],["Torii","Torii-Tore markieren den Übergang zum heiligen Bereich eines Schreins (神社, jinja)."],["Reinheit","Rituelle Reinheit — etwa durch Handwaschung oder Reinigungszeremonien (o-harai) — ist ein zentrales shintoistisches Konzept."]],quiz:[{q:'Was bedeutet "Shintō" wörtlich?',o:["Weg der Götter","Weg des Schwertes","Weg des Tees"],c:0},{q:"Was markiert ein Torii?",o:["Übergang zu einem heiligen Bereich","Einen Marktplatz","Ein Gerichtsgebäude"],c:0},{q:"Welches Konzept ist im Shintō zentral?",o:["Rituelle Reinheit","Erbsünde","Fegefeuer"],c:0},{q:"Hat Shintō eine zentrale heilige Gründerfigur wie andere Weltreligionen?",o:["Nein","Ja, Buddha","Ja, einen einzelnen Propheten"],c:0}]},{id:"rel-2",chapter:"Religion & Philosophie",title:"Buddhismus in Japan",facts:[["Herkunft","Der Buddhismus kam im 6. Jahrhundert über Korea und China nach Japan."],["Vielfalt der Schulen","Es entstanden mehrere Schulen, darunter Tendai, Shingon, Reines-Land-Buddhismus (Jōdo) und Zen."],["Parallele Praxis","Viele Menschen praktizieren Shintō und Buddhismus parallel — Geburt und Hochzeit oft shintoistisch, Bestattungen oft buddhistisch."],["Tōdai-ji","Der Tōdai-ji-Tempel in Nara mit seiner riesigen Buddha-Statue zeugt von der frühen buddhistischen Prägung Japans."]],quiz:[{q:"Woher kam der Buddhismus nach Japan?",o:["Aus Korea/China","Direkt aus Indien per Schiff","Aus Europa"],c:0},{q:"Welche buddhistische Schule betont besonders Meditation?",o:["Zen","Shintō","Konfuzianismus"],c:0},{q:"Was ist in Japan bei religiösen Anlässen typisch?",o:["Parallele Praxis von Shintō und Buddhismus","Ausschließlich eine Religion für alles","Verbot religiöser Praxis"],c:0},{q:"Welcher berühmte Tempel steht in Nara?",o:["Tōdai-ji","Kinkaku-ji","Sensō-ji"],c:0}]},{id:"rel-3",chapter:"Religion & Philosophie",title:"Zen-Buddhismus & Kampfkünste",facts:[["Zazen","Zen betont direkte Erfahrung und Sitzmeditation (座禅, zazen) statt intensives Schriftstudium."],["Samurai-Ethik","Zen ist eng mit der Ethik der Samurai und der Entwicklung japanischer Kampfkünste (Budō) verbunden."],["Ästhetischer Einfluss","Zen prägte Teezeremonie, Gartenkunst und Kalligraphie maßgeblich mit."],["Mushin",'Das Konzept "Mushin" (Nicht-Geist) beschreibt einen Zustand des Handelns ohne störendes Grübeln.']],quiz:[{q:"Was ist zazen?",o:["Sitzmeditation im Zen","Ein Schwerttyp","Eine Teesorte"],c:0},{q:"Womit ist Zen historisch eng verbunden?",o:["Samurai-Ethik und Kampfkünsten","Der Handelsschifffahrt","Der Landwirtschaft"],c:0},{q:"Was beeinflusste Zen unter anderem ästhetisch?",o:["Teezeremonie und Gartenkunst","Ausschließlich westliche Musik","Nur moderne Architektur"],c:0},{q:'Was beschreibt der Begriff "Mushin"?',o:["Einen Geisteszustand ohne störendes Grübeln","Einen Schwertkampfstil","Eine Tempelform"],c:0}]},{id:"rel-4",chapter:"Religion & Philosophie",title:"Feste, Rituale & Pilgerfahrten",facts:[["Matsuri","Matsuri sind lokale Schreinfeste mit Prozessionen, Musik und Verkaufsständen."],["O-Bon","Das sommerliche O-Bon-Fest dient dem Gedenken an verstorbene Vorfahren."],["Hatsumōde","Hatsumōde bezeichnet den ersten Schreinbesuch im neuen Jahr — ein wichtiges Ritual."],["88-Tempel-Pfad","Der Pilgerweg der 88 Tempel auf Shikoku verbindet zahlreiche buddhistische Stätten der Insel."]],quiz:[{q:"Was ist ein Matsuri?",o:["Ein lokales Schreinfest","Ein Gerichtsverfahren","Eine Steuerabgabe"],c:0},{q:"Wofür steht das O-Bon-Fest?",o:["Gedenken an verstorbene Vorfahren","Erntedank im Frühling","Feier der Kaisergeburt"],c:0},{q:"Was ist Hatsumōde?",o:["Der erste Schreinbesuch im neuen Jahr","Ein Hochzeitsritual","Ein Sportfest"],c:0},{q:"Wo verläuft der bekannte 88-Tempel-Pilgerweg?",o:["Auf der Insel Shikoku","In Hokkaido","In Tokyo"],c:0}]},{id:"rel-5",chapter:"Religion & Philosophie",title:"Glücksbringer, Omikuji & Aberglaube",facts:[["Omamori","Omamori sind kleine Stoffamulette, die man an Schreinen und Tempeln für einen bestimmten Zweck kauft — Verkehrssicherheit, Prüfungserfolg, Gesundheit, Liebe. Üblicherweise tauscht man sie einmal im Jahr."],["Omikuji","Omikuji sind gezogene Papier-Orakel. Fällt die Vorhersage schlecht aus, bindet man den Zettel oft an ein Gestell oder einen Ast am Schrein, um das Pech dort zurückzulassen."],["Ema","Ema sind kleine Holztäfelchen, auf die man einen Wunsch schreibt und die man am Schrein aufhängt — häufig vor Prüfungen oder bei Kinderwunsch."],["Zahlen & Alltagsglaube",'Die 4 (shi) klingt wie „Tod", die 9 (ku) wie „Leid" — beide werden z. B. bei Zimmer- und Stockwerksnummern oft ausgelassen. Der verbreitete Glaube, die Blutgruppe forme den Charakter, hat keine wissenschaftliche Grundlage.']],quiz:[{q:"Was ist ein omamori?",o:["Ein Glücksamulett vom Schrein oder Tempel","Ein Räucherstäbchen für zu Hause","Ein gedruckter Neujahrsgruß"],c:0},{q:"Was macht man oft mit einem schlechten omikuji?",o:["Am Schrein anbinden, um das Pech dort zu lassen","Sofort verbrennen","Eingerahmt zu Hause aufhängen"],c:0},{q:"Warum wird die Zahl 4 im Alltag oft gemieden?",o:['Sie klingt wie das Wort für „Tod"',"Sie gilt als zu große Zahl","Ein religiöses Gebot verbietet sie"],c:0},{q:"Wie ist der Glaube an Blutgruppen-Charaktere einzuordnen?",o:["Weit verbreitet, aber ohne wissenschaftliche Grundlage","Wissenschaftlich gut belegt","Amtlich in Ausweisen vermerkt und geprüft"],c:0}]},{id:"food-1",chapter:"Essen & Trinken",title:"Grundnahrung & Regionalküchen",facts:[["Reis als Basis",'Reis (米, kome) ist Grundnahrungsmittel — "gohan" bedeutet sowohl gekochter Reis als auch allgemein "Mahlzeit".'],["Dashi","Dashi, eine Grundbrühe aus Kombu-Alge und Bonito-Flocken, bildet die Basis unzähliger Gerichte."],["Regionale Vielfalt","Gerichte variieren stark je nach Region — etwa Okonomiyaki in Osaka oder sehr unterschiedliche Ramen-Stile."],["Fisch & Meeresfrüchte","Wegen der Insellage spielen Fisch und Meeresfrüchte traditionell eine zentrale Rolle in der Küche."]],quiz:[{q:'Was bedeutet "gohan" auch allgemein?',o:["Mahlzeit","Nur Fisch","Ein Getränk"],c:0},{q:"Was ist Dashi?",o:["Eine japanische Grundbrühe","Ein Reiswein","Ein Nudeltyp"],c:0},{q:"Wofür ist Osaka kulinarisch besonders bekannt?",o:["Okonomiyaki","Die Erfindung von Sushi","Weinanbau"],c:0},{q:"Warum spielt Fisch traditionell eine große Rolle?",o:["Wegen der Insellage Japans","Weil Fleisch verboten war","Ohne besonderen Grund"],c:0}]},{id:"food-2",chapter:"Essen & Trinken",title:"Teezeremonie & Teekultur",facts:[["Chadō","Chadō/Sadō (茶道) ist ein choreographiertes Ritual, in dem Achtsamkeit und Ästhetik im Zentrum stehen."],["Matcha","Matcha, fein gemahlener Grüntee, ist zentraler Bestandteil der Teezeremonie."],["Ichi-go ichi-e",'Das Konzept "Ichi-go ichi-e" besagt, dass jede Begegnung einzigartig und unwiederholbar ist.'],["Wabi-Sabi-Ästhetik","Teehäuser und -gärten sind bewusst schlicht gestaltet, geprägt von der Wabi-Sabi-Ästhetik."]],quiz:[{q:"Wie heißt die japanische Teezeremonie?",o:["Chadō / Sadō","Ikebana","Shodō"],c:0},{q:"Welcher Tee steht im Zentrum der Zeremonie?",o:["Matcha","Schwarztee","Oolong"],c:0},{q:'Was besagt "Ichi-go ichi-e"?',o:["Jede Begegnung ist einzigartig","Man sollte immer pünktlich sein","Tee muss kalt serviert werden"],c:0},{q:"Welche Ästhetik prägt Teehäuser typischerweise?",o:["Wabi-Sabi — bewusste Schlichtheit","Maximaler Prunk","Grelle Farben"],c:0}]},{id:"food-3",chapter:"Essen & Trinken",title:"Sake, Bier & Getränkekultur",facts:[["Sake","Sake (日本酒) wird aus fermentiertem Reis hergestellt, nicht destilliert."],["Shōchū","Shōchū ist eine destillierte Spirituose, oft aus Süßkartoffel, Gerste oder Reis."],["Biergeschichte","Bier wurde im 19. Jahrhundert eingeführt und ist heute mit Marken wie Asahi und Kirin sehr populär."],["Nomikai","Gemeinsames Trinken (Nomikai) ist ein wichtiger sozialer und beruflicher Anlass in Japan."]],quiz:[{q:"Wie wird Sake hergestellt?",o:["Fermentiert, nicht destilliert","Destilliert wie Whisky","Aus Trauben gebraut"],c:0},{q:"Was ist Shōchū?",o:["Eine destillierte Spirituose","Ein alkoholfreies Süßgetränk","Ein Teetyp"],c:0},{q:"Wann wurde Bier in Japan eingeführt?",o:["Im 19. Jahrhundert","In der Jomon-Zeit","Erst nach dem Jahr 2000"],c:0},{q:"Was ist ein Nomikai?",o:["Ein gemeinsamer Trinkanlass, oft beruflich","Ein Sportfest","Ein Tempelbesuch"],c:0}]},{id:"food-4",chapter:"Essen & Trinken",title:"Streetfood & moderne Esstrends",facts:[["Takoyaki & Yakitori","Frittierte Oktopusbällchen (Takoyaki) und gegrillte Spieße (Yakitori) gehören zum beliebten Streetfood."],["Konbini","Convenience Stores (Konbini) prägen den Alltag mit frischer, günstiger Küche rund um die Uhr."],["Bento","Ein Bento ist eine sorgfältig zusammengestellte Lunchbox, oft mit hohem gestalterischem Anspruch."],["Veganer Trend","In japanischen Großstädten wächst der Trend zu veganer und vegetarischer Küche zunehmend."]],quiz:[{q:"Was ist Takoyaki?",o:["Frittierte Oktopusbällchen","Ein Reisgericht mit Fisch","Ein Dessert"],c:0},{q:"Was zeichnet Konbini aus?",o:["Rund-um-die-Uhr frische, günstige Küche","Nur Souvenirverkauf","Ausschließlich Elektronik"],c:0},{q:"Was ist ein Bento?",o:["Eine sorgfältig gestaltete Lunchbox","Ein Trinkgefäß","Ein Festtagskimono"],c:0},{q:"Welcher Ernährungstrend wächst in japanischen Großstädten?",o:["Vegane/vegetarische Küche","Ausschließlich Rohkost","Verzicht auf Reis"],c:0}]},{id:"food-5",chapter:"Essen & Trinken",title:"Am Tisch: Sitten & Restauranttypen",facts:[["Tischformeln",'Vor dem Essen sagt man „itadakimasu", danach „gochisōsama (deshita)" — ein fester höflicher Rahmen um jede Mahlzeit, auch allein.'],["Stäbchen-Tabus","Stäbchen nie senkrecht in den Reis stecken und Essen nie von Stäbchen zu Stäbchen reichen — beides gehört zu Bestattungsriten. Auch nicht mit den Stäbchen zeigen oder Essen aufspießen."],["Geräusche bei Tisch","Nudeln hörbar zu schlürfen gilt als normal, nicht unhöflich. Als unangenehm gilt dagegen, sich bei Tisch die Nase zu putzen."],["Lokal-Typen","Typische Formen: izakaya (Kneipe mit kleinen Gerichten), teishoku-ya (Set-Menüs), kaiten-zushi (Sushi vom Band), rāmen-ya und das altmodische kissaten (Café). In vielen günstigen Lokalen kauft man am Automaten vorab einen Essensgutschein (食券)."]],quiz:[{q:"Was sagt man in Japan üblicherweise vor dem Essen?",o:['„Itadakimasu"','„Kampai"','„Sayōnara"'],c:0},{q:"Warum steckt man Stäbchen nicht senkrecht in den Reis?",o:["Es ähnelt einem Bestattungsritual","Der Reis wird dadurch schneller kalt","Es ist nur unpraktisch, sonst egal"],c:0},{q:"Wie wird lautes Schlürfen von Nudeln bewertet?",o:["Als normal, nicht unhöflich","Als grobe Beleidigung des Kochs","Nur bei kalten Soba erlaubt"],c:0},{q:"Wozu dient der 食券-Automat am Eingang mancher Lokale?",o:["Man kauft dort vorab einen Essensgutschein","Er zieht eine Wartenummer für einen Tisch","Er prüft den Ausweis auf das Mindestalter"],c:0}]},{id:"kult-1",chapter:"Kultur & Etikette",title:"Höflichkeit & Sprache im Alltag",facts:[["Keigo","Keigo (敬語) ist ein eigenes Höflichkeitssprachsystem mit mehreren Ebenen der Formalität."],["Verbeugung","Die Verbeugung (ojigi) ersetzt oft den Handschlag — Tiefe und Dauer signalisieren Respekt, Entschuldigung oder Dank."],["Visitenkarten","Visitenkarten (meishi) werden traditionell mit beiden Händen und sichtbarem Respekt überreicht."],["Honne vs. Tatemae",'Das Konzept "Honne vs. Tatemae" unterscheidet innere Gefühle von nach außen gezeigtem Verhalten.']],quiz:[{q:"Was ist Keigo?",o:["Ein Höflichkeitssprachsystem","Ein Kampfsport","Eine Tee-Sorte"],c:0},{q:"Was ersetzt in Japan oft den Handschlag?",o:["Die Verbeugung","Ein Winken","Ein Kuss"],c:0},{q:"Wie werden Visitenkarten typischerweise überreicht?",o:["Mit beiden Händen und Respekt","Achtlos hingeworfen","Nur mündlich weitergegeben"],c:0},{q:'Was beschreibt "Honne vs. Tatemae"?',o:["Innere Gefühle vs. nach außen gezeigtes Verhalten","Zwei Kampfsportarten","Zwei Reissorten"],c:0}]},{id:"kult-2",chapter:"Kultur & Etikette",title:"Familie & Gesellschaftsstruktur",facts:[["Wa",'Das Konzept "Wa" betont Gruppenharmonie und -zugehörigkeit als gesellschaftlichen Grundwert.'],["Ie-System","Das traditionelle Ie-System organisierte den Familienhaushalt mit männlicher Erbfolge — heute stark gewandelt."],["Senpai-Kōhai","Senpai-Kōhai-Beziehungen beschreiben die Hierarchie zwischen Erfahreneren und Jüngeren, prägend in Schule und Beruf."],["Gesellschaftlicher Wandel","Zunehmend prägen kleinere Haushalte und mehr Singlehaushalte moderne japanische Städte."]],quiz:[{q:"Welches Konzept betont Gruppenharmonie?",o:["Wa","Bushidō","Sakoku"],c:0},{q:"Was beschreibt eine Senpai-Kōhai-Beziehung?",o:["Hierarchie zwischen Erfahreneren und Jüngeren","Einen Handelsvertrag","Eine Tempelordnung"],c:0},{q:"Was war das traditionelle Ie-System?",o:["Ein Familienhaushalts-Konzept mit männlicher Erbfolge","Ein Steuersystem","Ein Bildungssystem"],c:0},{q:"Wie verändert sich die japanische Haushaltsstruktur zunehmend?",o:["Mehr Single- und kleinere Haushalte","Fast nur noch Großfamilien","Keine Veränderung seit Jahrhunderten"],c:0}]},{id:"kult-3",chapter:"Kultur & Etikette",title:"Feste & Jahreshöhepunkte",facts:[["Neujahr","Oshōgatsu, das japanische Neujahrsfest, gilt als das wichtigste Fest des Jahres."],["Kinder-Feste","Kodomo no Hi (Kindertag) und Hinamatsuri (Puppenfest) ehren im Jahresverlauf die Kinder der Familie."],["Sommerfeuerwerke","Feuerwerke (hanabi) und leichte Sommerkimonos (Yukata) prägen die heiße Jahreszeit."],["Momiji-gari","Momiji-gari, das herbstliche Betrachten der roten Ahornblätter, ist das herbstliche Gegenstück zum frühlingshaften Hanami."]],quiz:[{q:"Welches ist das wichtigste Fest des Jahres?",o:["Neujahr (oshōgatsu)","Halloween","Ostern"],c:0},{q:"Was ist Hinamatsuri?",o:["Ein Puppenfest zu Ehren von Mädchen","Ein Herbstfest","Ein Trauertag"],c:0},{q:'Was bezeichnet "Momiji-gari"?',o:["Das Betrachten der herbstlichen Ahornblätter","Eine Fischereitechnik","Ein Sportturnier"],c:0},{q:"Was trägt man häufig bei Sommerfesten?",o:["Yukata","Anzug","Rüstung"],c:0}]},{id:"kult-4",chapter:"Kultur & Etikette",title:"Geschenkkultur & Alltagsverhalten",facts:[["Omiyage","Omiyage sind Reise-Mitbringsel für Kollegen und Familie — eine fest etablierte Tradition."],["Genkan","Schuhe werden beim Betreten von Wohnungen traditionell im Eingangsbereich (genkan) ausgezogen."],["Geschenke überreichen","Geschenke werden oft aufwendig verpackt und mit beiden Händen überreicht."],["Soziale Normen","Pünktlichkeit und Disziplin beim Anstehen in Warteschlangen gelten als wichtige soziale Normen."]],quiz:[{q:"Was ist Omiyage?",o:["Reise-Mitbringsel für andere","Ein Trinkspiel","Ein Trauerritual"],c:0},{q:"Wo zieht man in Japan traditionell die Schuhe aus?",o:["Im genkan, dem Eingangsbereich","Nur im Schlafzimmer","Nirgends"],c:0},{q:"Wie werden Geschenke typischerweise überreicht?",o:["Aufwendig verpackt, mit beiden Händen","Formlos, ohne Verpackung","Nur postalisch"],c:0},{q:"Welche sozialen Normen gelten als besonders wichtig?",o:["Pünktlichkeit und Warteschlangendisziplin","Lautstärke und Spontanität","Improvisation ohne Regeln"],c:0}]},{id:"kunst-1",chapter:"Kunst & Architektur",title:"Kalligraphie & Malerei",facts:[["Shodō","Shodō (書道), die Kunst der Kalligraphie, macht Pinselführung und Tuscheverteilung ebenso wichtig wie die Zeichen selbst."],["Sumi-e","Sumi-e ist Tuschemalerei, oft reduziert auf wenige, gezielte Pinselstriche."],["Ukiyo-e als Popkunst","Ukiyo-e-Holzschnitte prägten die Popkunst der Edo-Zeit mit Landschaften, Schauspielern und Kurtisanen."],["Moderne Kunst","Zeitgenössische Künstler wie Takashi Murakami verbinden traditionelle Techniken mit globaler Pop-Art."]],quiz:[{q:"Was ist Shodō?",o:["Die Kunst der Kalligraphie","Ein Blumengesteck","Ein Baustil"],c:0},{q:"Was ist Sumi-e?",o:["Tuschemalerei","Ein Steinofen","Ein Kampfsport"],c:0},{q:"Was zeigten Ukiyo-e-Holzschnitte häufig?",o:["Landschaften, Schauspieler, Kurtisanen","Ausschließlich religiöse Szenen","Nur Tierdarstellungen"],c:0},{q:"Welcher zeitgenössische Künstler verbindet Tradition mit Pop-Art?",o:["Takashi Murakami","Katsushika Hokusai","Sen no Rikyū"],c:0}]},{id:"kunst-2",chapter:"Kunst & Architektur",title:"Ikebana & Gartenkunst",facts:[["Ikebana","Ikebana (生け花) betont bei der Blumensteckkunst bewussten Raum, klare Linien und gestaltete Leere."],["Karesansui","Karesansui-Gärten sind Trockenlandschaftsgärten aus Kies und Steinen, etwa am Ryōan-ji in Kyoto."],["Zen-Gärten","Zen-Gärten sollen zur Meditation anregen, häufig ganz ohne Wasser oder Pflanzen."],["Bonsai","Bonsai ist die Kunst, Bäume über Jahre hinweg in kunstvoller Miniaturform zu kultivieren."]],quiz:[{q:"Was betont Ikebana besonders?",o:["Raum, Linie und bewusste Leere","Maximale Blütenfülle","Symmetrie um jeden Preis"],c:0},{q:"Was ist ein Karesansui-Garten?",o:["Ein Trockenlandschaftsgarten mit Kies und Steinen","Ein tropischer Gewächshausgarten","Ein reiner Wassergarten"],c:0},{q:"Wofür ist der Ryōan-ji in Kyoto berühmt?",o:["Seinen Zen-Steingarten","Seine Kirschblüten-Allee","Seinen Weinanbau"],c:0},{q:"Was ist Bonsai?",o:["Die Kunst, Bäume in Miniaturform zu kultivieren","Ein Kampfsport","Eine Papierfalttechnik"],c:0}]},{id:"kunst-3",chapter:"Kunst & Architektur",title:"Tempel- & Schreinarchitektur",facts:[["Holzbauweise","Traditionelle Sakralbauten bestehen meist aus Holz, oft ganz ohne Nägel, nach jahrhundertealten Prinzipien."],["Älteste Holzbauten","Die Pagode am Hōryū-ji zählt zu den ältesten erhaltenen Holzbauten der Welt."],["Schrein vs. Tempel","Schreine (jinja) sind shintoistisch, Tempel (tera/-ji) buddhistisch — architektonisch oft unterscheidbar."],["Ise-jingū","Der Ise-jingū-Schrein wird traditionell alle 20 Jahre komplett rituell neu errichtet, um Handwerkstradition zu erhalten."]],quiz:[{q:"Woraus bestehen traditionelle japanische Sakralbauten meist?",o:["Holz, oft ohne Nägel","Stahlbeton","Backstein"],c:0},{q:"Was gehört zu den ältesten erhaltenen Holzbauten der Welt?",o:["Die Pagode am Hōryū-ji","Der Kaiserpalast Tokyo","Die Burg Himeji"],c:0},{q:"Wie unterscheidet man grob Schrein von Tempel?",o:["Schrein = Shintō, Tempel = buddhistisch","Beides ist identisch","Schrein ist immer größer"],c:0},{q:"Was geschieht alle 20 Jahre am Ise-jingū?",o:["Ein kompletter ritueller Wiederaufbau","Ein Kaiserbesuch","Eine dauerhafte Schließung"],c:0}]},{id:"kunst-4",chapter:"Kunst & Architektur",title:"Theater & Handwerkskunst",facts:[["Nō-Theater","Nō ist stilisiertes Maskentheater mit langsamer, ritueller Bewegung."],["Kabuki","Kabuki ist farbenprächtiges, dynamisches Theater, traditionell ausschließlich von Männern gespielt."],["Bunraku","Bunraku ist kunstvolles Puppentheater mit lebensgroßen Figuren, geführt von mehreren Puppenspielern gleichzeitig."],["Handwerkskunst","Traditionelles Handwerk wie Raku-Keramik und Lackkunst (urushi) gilt als eigenständige Kunstform."]],quiz:[{q:"Was zeichnet Nō-Theater aus?",o:["Stilisierte Masken und langsame Bewegung","Schnelle Popmusik","Improvisierte Comedy"],c:0},{q:"Wer spielt traditionell alle Rollen im Kabuki?",o:["Ausschließlich Männer","Nur Frauen","Kinder"],c:0},{q:"Was ist Bunraku?",o:["Kunstvolles Puppentheater","Ein Schwertkampfstil","Eine Teezeremonie-Form"],c:0},{q:"Was ist urushi?",o:["Japanische Lackkunst","Ein Reisgericht","Ein Kampfsport"],c:0}]},{id:"kunst-5",chapter:"Kunst & Architektur",title:"Kimono, Mode & Produktdesign",facts:[["Der Kimono","Der Kimono wird bei Lebenden immer rechte Seite unter die linke geschlagen (andersherum nur bei Verstorbenen). Getragen wird er heute vor allem zu Hochzeiten, zur Volljährigkeitsfeier, zur Teezeremonie und zu Festen."],["Der Yukata","Der yukata ist ein leichter Baumwoll-Kimono für den Sommer, für Feste und für den Aufenthalt im Onsen-Ryokan — die alltagstaugliche, ungezwungene Variante."],["Straßenmode","Viertel wie Harajuku in Tokyo wurden ab den 1990er-Jahren weltweit für auffällige, experimentelle Jugendmode bekannt. Heute ist das Bild ruhiger, der Ruf als Modeviertel bleibt."],["Produktdesign",'Es gibt eine starke Tradition zurückhaltenden, funktionalen Designs — von der „No-Name"-Marke Muji über Kameras bis zu Schreibwaren. Oft wird sie auf dieselbe Ästhetik der Reduktion zurückgeführt wie Garten und Teeweg.']],quiz:[{q:"Wie wird ein Kimono bei Lebenden geschlossen?",o:["Rechte Seite unter die linke","Linke Seite unter die rechte","Beide Seiten bleiben offen"],c:0},{q:"Was ist ein yukata?",o:["Ein leichter Baumwoll-Kimono für Sommer und Onsen","Ein wattierter Wintermantel","Ein traditionelles Schuhwerk"],c:0},{q:"Wofür wurde das Viertel Harajuku international bekannt?",o:["Für auffällige Jugendmode","Für den Automobilhandel","Für seine Fischmärkte"],c:0},{q:"Was kennzeichnet japanisches Produktdesign oft?",o:["Zurückhaltung und Funktion","Möglichst viel Zierrat","Grelle Farben als Standard"],c:0}]},{id:"mod-4",chapter:"Technologie & Innovation",title:"Technologie & Innovation",facts:[["Robotik-Pionier","Japan spielt seit Jahrzehnten eine Pionierrolle bei Industrie- und Servicerobotern."],["Shinkansen","Der Shinkansen fährt seit 1964 und gilt als Symbol technischer Präzision."],["Elektronik & Halbleiter","Seit den 1970er/80er-Jahren spielte Japan eine führende Rolle in Unterhaltungselektronik und Halbleiterproduktion."],["KI gegen Arbeitskräftemangel","Wegen demografischem Wandel und Arbeitskräftemangel investiert Japan verstärkt in Robotik und KI."]],quiz:[{q:"Seit wann verkehrt der Shinkansen?",o:["Seit 1964","Seit 1868","Seit 2000"],c:0},{q:"Worin liegt eine japanische Technologie-Pionierrolle?",o:["Robotik","Weinbau","Landwirtschaftliche Handarbeit"],c:0},{q:"Warum investiert Japan verstärkt in Robotik/KI?",o:["Wegen demografischem Wandel und Arbeitskräftemangel","Wegen Rohstoffüberschuss","Ohne besonderen Grund"],c:0},{q:"In welchem Bereich war Japan seit den 1970er/80ern führend?",o:["Unterhaltungselektronik und Halbleiter","Ausschließlich Textilindustrie","Bergbau"],c:0}]},{id:"tech-2",chapter:"Technologie & Innovation",title:"Shinkansen & Ingenieurskultur",facts:[["1964","Zur Olympiade in Tokyo eröffnete mit dem Tōkaidō-Shinkansen die erste Hochgeschwindigkeitsstrecke der Welt; heute reicht das Netz von Kyūshū bis Hokkaidō."],["Pünktlichkeit","Die durchschnittliche Verspätung liegt bei unter einer Minute pro Jahr und Zug — inklusive wetter- und erdbebenbedingter Ausfälle."],["Sicherheit","In fast 60 Jahren Betrieb gab es keinen einzigen Todesfall durch Entgleisung oder Zusammenstoß im Regelbetrieb; ein Frühwarnsystem stoppt Züge bei Erdbeben automatisch."],["Monozukuri",'Der Begriff „monozukuri" (das Herstellen von Dingen) fasst ein Ingenieurs-Selbstverständnis, das Präzision, ständige Verbesserung (kaizen) und Handwerksstolz verbindet.']],quiz:[{q:"Wann fuhr der erste Shinkansen?",o:["1964","1945","1988"],c:0},{q:"Wie groß ist die typische jährliche Durchschnittsverspätung?",o:["unter einer Minute","etwa zehn Minuten","eine halbe Stunde"],c:0},{q:'Was beschreibt „monozukuri"?',o:["handwerklich-präzises Herstellen","eine Zugklasse","ein Firmenname"],c:0}]},{id:"tech-3",chapter:"Technologie & Innovation",title:"Elektronik & Halbleiter — Aufstieg und Wandel",facts:[["Nachkriegsboom",'Firmen wie Sony, Panasonic, Toshiba und Sharp machten „Made in Japan" ab den 1970ern zum Qualitätssiegel für Unterhaltungselektronik.'],["Walkman & Co.","Der Sony Walkman (1979) prägte weltweit mobiles Musikhören; Nintendo und Sega definierten die Heimvideospiel-Industrie mit."],["Der Rückschlag","In den 2000ern verloren japanische Hersteller bei Smartphones und Displays Marktanteile an koreanische und chinesische Konkurrenz."],["Heutige Stärke","Japan ist führend bei Bauteilen statt Endgeräten: Bildsensoren, Spezialchemie für Chipfertigung, Präzisionsmaschinen und Robotik."]],quiz:[{q:"Welches Gerät prägte mobiles Musikhören?",o:["Sony Walkman","iPhone","MiniDisc-Recorder von Philips"],c:0},{q:"Wo ist Japans Elektronikindustrie heute besonders stark?",o:["Bauteile und Fertigungsmaschinen","Smartphones","Suchmaschinen"],c:0},{q:"Wann geriet die Endgeräte-Sparte unter Druck?",o:["in den 2000ern","in den 1960ern","nie"],c:0}]},{id:"tech-4",chapter:"Technologie & Innovation",title:"Roboter & Automatisierung",facts:[["Industrieroboter","Japan gehört zu den Ländern mit der höchsten Roboterdichte in der Fertigung; FANUC und Yaskawa zählen zu den weltgrößten Herstellern."],["Alternde Gesellschaft","Pflege- und Assistenzroboter werden erprobt, um dem Arbeitskräftemangel in einer schrumpfenden, alternden Bevölkerung zu begegnen."],["Kultur","Von Astro Boy bis Gundam ist der freundliche Roboter fest in der Populärkultur verankert — anders als in vielen westlichen Erzählungen."],["Grenzen","Viele Vorzeige-Roboter bleiben Prototypen; im Alltag dominieren unsichtbare Automatisierung, Verkaufsautomaten und Selbstbedienungskassen."]],quiz:[{q:"Warum wird an Pflegerobotern geforscht?",o:["Arbeitskräftemangel in alternder Gesellschaft","Exportverbot für Menschen","Tourismus"],c:0},{q:"Welche Firmen bauen Industrieroboter?",o:["FANUC und Yaskawa","Sony und Nintendo","JR und ANA"],c:0},{q:"Wie steht die Populärkultur zum Roboter?",o:["überwiegend positiv besetzt","durchweg als Bedrohung","kommt nicht vor"],c:0}]},{id:"tech-5",chapter:"Technologie & Innovation",title:'Digitaler Alltag & der „Galápagos"-Effekt',facts:[["Keitai-Kultur",'Japans Mobiltelefone waren um 2000 technisch führend (mobiles Internet, Bezahlen, TV), entwickelten sich aber isoliert vom Weltmarkt — daher „Galápagos-Handys".'],["Bargeld & Siegel","Trotz Hightech-Image hielten sich Bargeld, Faxgeräte und der persönliche Namensstempel (hanko) lange; erst seit ~2020 beschleunigt sich die Digitalisierung von Verwaltung und Bezahlen."],["IC-Karten","Aufladbare Karten wie Suica/Pasmo verbinden Nahverkehr, Kiosk und Automaten zu einem alltäglichen bargeldlosen System."],["Digitalbehörde",'2021 entstand die „Digital Agency", um zersplitterte Behörden-IT zu bündeln und die „My Number"-Ausweisnummer breiter nutzbar zu machen.']],quiz:[{q:'Was meint „Galápagos-Effekt" bei japanischer Technik?',o:["isolierte Weiterentwicklung abseits des Weltmarkts","Technik von den Galápagos-Inseln","besonders umweltfreundliche Geräte"],c:0},{q:"Wofür stehen Suica und Pasmo?",o:["aufladbare IC-Karten","Zugtypen","Mobilfunkanbieter"],c:0},{q:"Was hielt sich trotz Hightech-Image lange?",o:["Bargeld, Fax und Namensstempel","Schreibmaschinen","Telegramme"],c:0}]},{id:"local-1",chapter:"Alltag wie ein Local",title:"Öffentlicher Nahverkehr",facts:[["IC-Karten","Bargeldlose IC-Karten wie Suica oder Pasmo ermöglichen Fahrten in Bussen und Bahnen und funktionieren oft auch als Zahlungsmittel in Läden."],["Pünktlichkeit","Japanische Züge gelten als extrem pünktlich — schon eine Verspätung von wenigen Minuten wird oft eigens angekündigt und entschuldigt."],["Ruhe-Etikette","Telefonieren in Zügen gilt als unhöflich; Handys werden meist lautlos gestellt."],["Frauenwaggons","Zu Stoßzeiten gibt es in manchen Städten spezielle Zugwaggons nur für Frauen, um Belästigung vorzubeugen."]],quiz:[{q:"Was sind Suica/Pasmo?",o:["Bargeldlose IC-Fahrkarten","Zugtickets nur für Touristen","Taxi-Apps"],c:0},{q:"Wie heißt eine bekannte bargeldlose Fahrkarte in Tokyo?",a:"Suica"},{q:"In japanischen Zügen gilt lautes Telefonieren als gesellschaftlich akzeptiert.",o:["Wahr","Falsch"],c:1},{q:"Wozu dienen spezielle Frauenwaggons zu Stoßzeiten?",o:["Schutz vor Belästigung","Sie sind für Kinder reserviert","Sie sind für Personal reserviert"],c:0}]},{id:"local-2",chapter:"Alltag wie ein Local",title:"Onsen & Bäder",facts:[["Onsen","Onsen sind heiße Quellen, meist geschlechtergetrennt, und werden nackt besucht — Badekleidung ist unüblich."],["Waschen vor dem Baden","Vor dem Eintauchen ist gründliches Waschen und Duschen an den Waschplätzen Pflicht."],["Tattoo-Regeln","Viele traditionelle Onsen erlauben sichtbare Tattoos noch immer nicht — historisch mit der Yakuza assoziiert."],["Sento","Sento sind öffentliche Stadtbäder ohne natürliche heiße Quelle, mit ähnlicher Etikette wie Onsen."]],quiz:[{q:"Was muss man vor dem Eintauchen in ein Onsen tun?",o:["Sich gründlich waschen","Badekleidung anziehen","Nichts Besonderes"],c:0},{q:"In traditionellen Onsen badet man für gewöhnlich mit Badeanzug.",o:["Wahr","Falsch"],c:1},{q:"Warum sind Tattoos in vielen Onsen historisch unerwünscht?",o:["Assoziation mit der Yakuza","Hygienevorschriften","Ein religiöses Verbot"],c:0},{q:"Wie heißen öffentliche Stadtbäder ohne natürliche heiße Quelle?",a:"Sento"}]},{id:"local-3",chapter:"Alltag wie ein Local",title:"Convenience-Store-Kultur",facts:[["Überall verfügbar","Konbini wie 7-Eleven, Lawson oder FamilyMart sind praktisch an jeder Ecke zu finden, viele rund um die Uhr geöffnet."],["Mehr als Einkaufen","In Konbini lassen sich Rechnungen bezahlen, Pakete verschicken, Tickets kaufen und Geld am Automaten abheben."],["Frische Lieferungen","Bento und Onigiri werden mehrmals täglich frisch angeliefert, statt lange im Regal zu stehen."],["Sitzbereiche","Manche Konbini bieten kleine Sitzbereiche, um Gekauftes direkt vor Ort zu essen."]],quiz:[{q:"Was kann man in einem Konbini außer Einkaufen noch erledigen?",o:["Rechnungen zahlen und Pakete verschicken","Nur Zeitungen kaufen","Nichts weiter"],c:0},{q:"Konbini haben in Japan meist nur eingeschränkte Öffnungszeiten.",o:["Wahr","Falsch"],c:1},{q:"Welche Kette zählt zu den bekannten Konbini in Japan?",o:["7-Eleven","Walmart","Aldi"],c:0},{q:"Wie heißt die japanische Reisball-Spezialität, die in Konbini beliebt ist?",a:"Onigiri"}]},{id:"local-4",chapter:"Alltag wie ein Local",title:"Ausgehen: Izakaya & Karaoke",facts:[["Izakaya","Izakaya sind gemütliche Kneipen mit kleinen Gerichten zum Teilen, beliebt für den Ausklang nach der Arbeit."],["Otoshi","Otoshi ist ein kleiner Pflicht-Snack zu Beginn, der meist automatisch mit der Sitzplatzgebühr berechnet wird."],["Private Karaoke-Räume","Karaoke wird in Japan meist in gebuchten Privaträumen gesungen, nicht auf offener Bühne vor Fremden."],["Nomihōdai","Nomihōdai bezeichnet All-you-can-drink-Angebote für einen festgelegten Zeitraum."]],quiz:[{q:"Was ist ein Izakaya?",o:["Eine gemütliche Kneipe mit kleinen Gerichten","Ein Fine-Dining-Restaurant","Ein Fastfood-Laden"],c:0},{q:"Was ist Otoshi?",o:["Ein kleiner Pflicht-Snack zu Beginn","Ein Trinkspiel","Eine Nachspeise"],c:0},{q:"Karaoke wird in Japan meist auf einer offenen Bühne vor Fremden gesungen.",o:["Wahr","Falsch"],c:1},{q:"Wie nennt man All-you-can-drink-Angebote für einen festen Zeitraum?",o:["Nomihōdai","Otoshi","Izakaya"],c:0}]},{id:"local-5",chapter:"Alltag wie ein Local",title:"Fettnäpfchen & Praktisches vermeiden",facts:[["Stäbchen-Etikette","Stäbchen niemals senkrecht in den Reis stecken — das erinnert an ein Totenritual."],["Trinkgeld","Trinkgeld ist in Japan unüblich und kann sogar als unhöflich empfunden werden."],["Essen unterwegs","Auf offener Straße oder im Gehen zu essen gilt vielerorts als unpassend."],["Das rettende Wort",'Bei Unsicherheit hilft ein höfliches "Sumimasen" (Entschuldigung/Verzeihung) fast immer weiter.']],quiz:[{q:"Warum steckt man Stäbchen nicht senkrecht in den Reis?",o:["Es erinnert an ein Totenritual","Es bricht die Stäbchen","Es ist zu langsam"],c:0},{q:"In Japan ist es üblich und erwartet, Trinkgeld zu geben.",o:["Wahr","Falsch"],c:1},{q:"Was gilt vielerorts als unpassend in der Öffentlichkeit?",o:["Essen im Gehen auf der Straße","Sich verbeugen","In der Schlange warten"],c:0},{q:"Welches Wort hilft bei Unsicherheit fast immer weiter?",o:["Sumimasen","Ganbatte","Otsukaresama"],c:0}]},{id:"city-1",chapter:"Städte & Regionen",title:"Tokyo",facts:[["Hauptstadt seit 1868","Tokyo ist seit der Meiji-Restauration 1868 Hauptstadt Japans, zuvor war es Kyoto."],["23 Bezirke","Der Kern Tokyos besteht aus 23 Spezialbezirken, dazu kommen zahlreiche weitere Städte und Gemeinden im Großraum."],["Shibuya-Kreuzung","Die Shibuya-Kreuzung gilt als eine der belebtesten Fußgängerkreuzungen der Welt."],["Kontraste","Tokyo vereint Hochmoderne wie Shinjuku und Akihabara mit traditionellen Vierteln wie Asakusa."]],quiz:[{q:"Seit wann ist Tokyo Hauptstadt Japans?",o:["1868","1603","1945"],c:0},{q:"Aus wie vielen Spezialbezirken besteht der Kern Tokyos?",a:"23"},{q:"Welche Kreuzung gilt als eine der belebtesten der Welt?",o:["Die Shibuya-Kreuzung","Die Ginza-Kreuzung","Die Ueno-Kreuzung"],c:0},{q:"Tokyo besteht ausschließlich aus modernen Vierteln ohne traditionelle Bereiche.",o:["Wahr","Falsch"],c:1}]},{id:"city-2",chapter:"Städte & Regionen",title:"Kyoto",facts:[["Über 1000 Jahre Kaiserstadt","Kyoto war von 794 bis 1868 die Kaiserstadt Japans."],["Tempeldichte","Kyoto beherbergt über 1.600 buddhistische Tempel und rund 400 Shintō-Schreine."],["Gion","Das Viertel Gion ist bekannt für gut erhaltene Geisha- und Geiko-Kultur."],["Wahrzeichen","Der goldene Kinkaku-ji und die Bambushaine von Arashiyama zählen zu den bekanntesten Sehenswürdigkeiten Kyotos."]],quiz:[{q:"Wie lange war Kyoto Kaiserstadt Japans?",o:["Über 1000 Jahre","Etwa 50 Jahre","Etwa 300 Jahre"],c:0},{q:"Wie viele buddhistische Tempel besitzt Kyoto ungefähr?",o:["Über 1.600","Etwa 50","Etwa 300"],c:0},{q:"Welches Viertel ist besonders für Geisha-Kultur bekannt?",o:["Gion","Akihabara","Shinjuku"],c:0},{q:"Kyoto war nie Hauptstadt Japans.",o:["Wahr","Falsch"],c:1}]},{id:"city-3",chapter:"Städte & Regionen",title:"Osaka",facts:[["Zweitgrößte Metropolregion","Osaka ist die zweitgrößte Metropolregion Japans und ein pulsierendes Wirtschafts- und Esszentrum."],['"Küche Japans"','Osaka wird oft als "Tenka no Daidokoro" — die Küche Japans — bezeichnet.'],["Burg Osaka","Die Burg Osaka war zentral für die Machtbasis von Toyotomi Hideyoshi."],["Direkte Mentalität","Die Bewohner Osakas gelten im Vergleich zu Tokyo als direkter und humorvoller."]],quiz:[{q:"Wofür ist Osaka kulinarisch besonders bekannt?",o:['Als "Küche Japans"',"Als Teeanbau-Zentrum","Als Weinregion"],c:0},{q:"Wer nutzte die Burg Osaka als Machtbasis?",o:["Toyotomi Hideyoshi","Kaiser Meiji","Minamoto no Yoritomo"],c:0},{q:"Osaka gilt traditionell als zurückhaltender und förmlicher als Tokyo.",o:["Wahr","Falsch"],c:1},{q:"An welcher Stelle steht Osakas Metropolregion größenmäßig in Japan? (nur die Zahl)",a:"2"}]},{id:"city-4",chapter:"Städte & Regionen",title:"Hokkaido",facts:[["Nördlichste Hauptinsel","Hokkaido ist die nördlichste Hauptinsel Japans, bekannt für kalte Winter und starken Schneefall."],["Ainu-Kultur","Hokkaido ist Heimat der indigenen Ainu-Kultur mit eigener Sprache und eigenen Traditionen."],["Landwirtschaft","Die Insel ist bekannt für Milchprodukte, Kartoffeln und weitläufige Lavendelfelder."],["Sapporo","Sapporo, die größte Stadt Hokkaidos, ist für ihr Winterfestival (Yuki Matsuri) berühmt."]],quiz:[{q:"Welche indigene Kultur ist besonders mit Hokkaido verbunden?",o:["Die Ainu","Die Ryūkyū","Die Yamato"],c:0},{q:"Wofür ist Hokkaido landwirtschaftlich bekannt?",o:["Milchprodukte und Kartoffeln","Reisterrassen","Teeanbau"],c:0},{q:"Wie heißt die größte Stadt Hokkaidos?",a:"Sapporo"},{q:"Hokkaido ist die südlichste Hauptinsel Japans.",o:["Wahr","Falsch"],c:1}]},{id:"city-5",chapter:"Städte & Regionen",title:"Okinawa",facts:[["Königreich Ryūkyū","Okinawa war bis 1879 das unabhängige Königreich Ryūkyū mit eigener Kultur und Sprache."],['"Blue Zone"','Okinawa gilt als eine der "Blue Zones" der Welt mit außergewöhnlich hoher Lebenserwartung.'],["Eigene Küche","Die Küche Okinawas unterscheidet sich deutlich vom Rest Japans, etwa mit Goya (Bittermelone) und Awamori (Reisschnaps)."],["Subtropisches Klima","Die Inselkette hat subtropisches Klima und ist kulturell eigenständig geprägt."]],quiz:[{q:"Was war Okinawa bis 1879?",o:["Das unabhängige Königreich Ryūkyū","Eine chinesische Provinz","Unbewohnt"],c:0},{q:'Okinawa gilt als eine der "Blue Zones" mit besonders hoher Lebenserwartung.',o:["Wahr","Falsch"],c:0},{q:"Was ist Awamori?",o:["Ein Reisschnaps aus Okinawa","Ein Teetyp","Ein Kampfsport"],c:0},{q:"Welches Klima hat Okinawa?",o:["Subtropisch","Subarktisch","Wüstenklima"],c:0}]},{id:"sport-1",chapter:"Sport & Freizeit",title:"Sumo",facts:[["Nationalsport mit Tradition","Sumo gilt als Japans Nationalsport mit jahrhundertealten shintoistischen Wurzeln."],["Trainingsställe","Rikishi (Sumo-Ringer) leben und trainieren oft in streng organisierten Trainingsställen (heya)."],["Regeln","Ziel ist es, den Gegner aus dem Ring zu drängen oder ihn zu Boden zu bringen."],["Yokozuna","Die höchste erreichbare Rangstufe im Sumo heißt Yokozuna."]],quiz:[{q:"Welche religiösen Wurzeln hat Sumo?",o:["Shintoistische Wurzeln","Buddhistische Wurzeln","Keine religiösen Bezüge"],c:0},{q:"Wie heißt die höchste Rangstufe im Sumo?",a:"Yokozuna"},{q:"Wo leben Sumo-Ringer meist während ihrer Karriere?",o:["In Trainingsställen (heya)","Zuhause bei der Familie","In Hotels"],c:0},{q:"Ziel im Sumo ist es, den Gegner aus dem Ring zu drängen oder zu Fall zu bringen.",o:["Wahr","Falsch"],c:0}]},{id:"sport-2",chapter:"Sport & Freizeit",title:"Kampfkünste (Budō)",facts:[["Vielfalt der Budō","Judo, Karate, Kendo und Aikido zählen zu den bekanntesten japanischen Kampfkünsten."],["Jigoro Kano","Judo wurde Ende des 19. Jahrhunderts von Jigoro Kano systematisiert."],["Kendo-Ausrüstung","Kendo nutzt Bambusschwerter (shinai) und schützende Ausrüstung (bōgu)."],["Charakterbildung","Viele Budō-Disziplinen betonen Charakterbildung ebenso wie körperliche Technik."]],quiz:[{q:"Wer systematisierte Judo?",o:["Jigoro Kano","Miyamoto Musashi","Oda Nobunaga"],c:0},{q:"Welche Waffe wird beim Kendo verwendet?",o:["Ein Bambusschwert (shinai)","Ein echtes Katana","Ein Speer"],c:0},{q:"Budō-Disziplinen legen ausschließlich Wert auf körperliche Stärke, nicht auf Charakter.",o:["Wahr","Falsch"],c:1},{q:"Welche Kampfkunst gehört NICHT zu den klassischen japanischen Budō-Formen?",o:["Boxen","Judo","Kendo"],c:0}]},{id:"sport-3",chapter:"Sport & Freizeit",title:"Baseball & moderne Sportkultur",facts:[["Yakyū","Baseball (Yakyū) ist seit dem späten 19. Jahrhundert extrem populär und wird oft als heimlicher Nationalsport bezeichnet."],["Kōshien","Das Kōshien-Highschool-Turnier genießt landesweite mediale Aufmerksamkeit."],["J-League","Fußball gewinnt seit der Gründung der J-League 1993 stetig an Popularität."],["Breitensport","Marathonlauf und Wandern sind beliebte Freizeitaktivitäten quer durch alle Altersgruppen."]],quiz:[{q:"Wie wird Baseball auf Japanisch genannt?",o:["Yakyū","Sumo","Judo"],c:0},{q:"In welchem Jahr wurde die japanische Fußball-J-League gegründet?",a:"1993"},{q:"Welches Turnier genießt landesweite Aufmerksamkeit im Highschool-Baseball?",o:["Kōshien","Yokozuna-Cup","Ryūkyū-Liga"],c:0},{q:"Fußball ist seit den 1990er-Jahren in Japan zunehmend populär geworden.",o:["Wahr","Falsch"],c:0}]},{id:"sport-4",chapter:"Sport & Freizeit",title:"Wintersport",facts:[["Skigebiete","Regionen wie Niseko auf Hokkaido und Hakuba in den Japanischen Alpen sind international für ihren außergewöhnlich trockenen Pulverschnee bekannt und ziehen viele ausländische Wintersportler an."],["Olympische Winterspiele","Japan richtete die Olympischen Winterspiele bereits zweimal aus: 1972 in Sapporo und 1998 in Nagano."],["Eiskunstlauf","Eiskunstlauf genießt in Japan besonders große Popularität, mit international erfolgreichen Sportlern wie Yuzuru Hanyu."],["Yuki Matsuri","Neben dem sportlichen Wintersport ist auch das winterliche Schneefest in Sapporo (Yuki Matsuri) mit riesigen Schneeskulpturen ein beliebtes saisonales Ereignis."]],quiz:[{q:"Wofür sind Niseko und Hakuba international bekannt?",o:["Außergewöhnlich trockener Pulverschnee","Sommerliche Strände","Wüstenlandschaften"],c:0},{q:"In welchen Jahren fanden Olympische Winterspiele in Japan statt?",o:["1972 und 1998","1964 und 2020","1988 und 2002"],c:0},{q:"In welcher Wintersportart ist Japan international besonders erfolgreich?",o:["Eiskunstlauf","Bobsport","Skispringen ausschließlich"],c:0},{q:"Was ist das Yuki Matsuri?",o:["Ein winterliches Schneefest mit Schneeskulpturen in Sapporo","Ein Sommerfeuerwerk","Ein Baseball-Turnier"],c:0}]},{id:"sport-5",chapter:"Sport & Freizeit",title:"Freizeit & Fitness im Alltag",facts:[["Rajio Taiso","Rajio Taiso (ラジオ体操), eine kurze Radio-Gymnastikroutine, wird seit den 1920er-Jahren landesweit ausgestrahlt und morgens von Schulen, Firmen und Senioren gemeinsam durchgeführt."],["Golf","Golf ist besonders im Geschäftsleben beliebt und wird oft auch zur informellen Pflege beruflicher Beziehungen genutzt."],["Gateball","Gateball, eine dem Krocket ähnliche Mannschaftssportart, erfreut sich vor allem bei älteren Menschen großer Beliebtheit."],["Fuji-Besteigung","Die Besteigung des Fuji während der offiziellen Bergsaison im Sommer ist eine beliebte Freizeitaktivität, die jährlich hunderttausende Wanderer anzieht."]],quiz:[{q:"Was ist Rajio Taiso?",o:["Eine landesweit ausgestrahlte Radio-Gymnastikroutine","Ein Radiosender nur für Sportnachrichten","Ein Kampfsport"],c:0},{q:"Wofür wird Golf in Japan neben dem Sport oft genutzt?",o:["Zur informellen Pflege beruflicher Beziehungen","Ausschließlich als Kindersport","Als Ersatz für Baseball"],c:0},{q:"Welcher Sportart ähnelt Gateball?",o:["Krocket","Baseball","Tischtennis"],c:0},{q:"Wann ist die Besteigung des Fuji offiziell möglich?",o:["Während der Bergsaison im Sommer","Nur im tiefsten Winter","Ganzjährig ohne Einschränkung"],c:0}]},{id:"pop-1",chapter:"Popkultur",title:"Anime — Geschichte & Industrie",facts:[["Begriffsherkunft",'Der Begriff "Anime" ist die japanische Kurzform von "Animation" und bezeichnet dort jede Art von Zeichentrick — im Ausland steht er speziell für japanische Produktionen.'],["Osamu Tezuka",'Osamu Tezuka gilt mit Werken wie "Astro Boy" (1963) als einer der Väter des modernen Anime und prägte den charakteristischen großäugigen Zeichenstil.'],["Studio Ghibli",'Studio Ghibli, 1985 von Hayao Miyazaki und Isao Takahata gegründet, gehört mit Filmen wie "Prinzessin Mononoke" und "Chihiros Reise ins Zauberland" zu den international bekanntesten Anime-Produktionen.'],["Saison-System","Neue Anime-Serien starten meist gebündelt zu Beginn jeder Jahreszeit (Frühling, Sommer, Herbst, Winter) — das sogenannte Saison-System der Industrie."]],quiz:[{q:'Was bedeutet der japanische Begriff "Anime" wörtlich?',o:["Animation (allgemein)","Nur Zeichentrick für Kinder","Comic auf Papier"],c:0},{q:"Wer gilt als einer der Väter des modernen Anime?",o:["Osamu Tezuka","Hayao Miyazaki","Akira Toriyama"],c:0},{q:"Welches Studio wurde 1985 von Miyazaki und Takahata gegründet?",o:["Studio Ghibli","Toei Animation","Sunrise"],c:0},{q:"Wonach richtet sich, wann viele neue Anime-Serien starten?",o:["Nach einem Saisonsystem (vier Mal im Jahr)","Nur einmal jährlich im Januar","Völlig unregelmäßig"],c:0}]},{id:"pop-2",chapter:"Popkultur",title:"Manga — Kultur & Industrie",facts:[["Leserichtung","Manga werden traditionell von rechts nach links gelesen — internationale Ausgaben behalten diese Leserichtung heute oft bewusst bei."],["Zielgruppen-Genres","Manga-Magazine richten sich nach klaren Zielgruppen: Shōnen (junge Männer), Shōjo (junge Frauen), Seinen (erwachsene Männer) und Josei (erwachsene Frauen) — mit jeweils eigenen Themen und Zeichenstilen."],["Weekly Shōnen Jump",'Das wöchentliche Magazin "Weekly Shōnen Jump" veröffentlichte Serien wie "Dragon Ball", "One Piece" und "Naruto" und zählt zu den auflagenstärksten Zeitschriften Japans überhaupt.'],["Manga-Kissa","In sogenannten Manga-Kissa (Manga-Cafés) kann man gegen Gebühr stundenlang in riesigen Manga-Sammlungen lesen — viele bieten zusätzlich Dusche und Übernachtungsmöglichkeit."]],quiz:[{q:"In welche Richtung werden Manga traditionell gelesen?",o:["Von rechts nach links","Von links nach rechts","Von oben nach unten"],c:0},{q:'Für welche Zielgruppe ist "Shōjo" gedacht?',o:["Junge Frauen","Junge Männer","Kinder unter 6"],c:0},{q:'Welche Serien erschienen im "Weekly Shōnen Jump"?',o:["Dragon Ball, One Piece, Naruto","Nur Sportmanga","Ausschließlich Liebesgeschichten"],c:0},{q:"Was ist ein Manga-Kissa?",o:["Ein Café zum stundenweisen Manga-Lesen","Ein Verlag","Eine Zeichenschule"],c:0}]},{id:"pop-3",chapter:"Popkultur",title:"Videospiele — Japan als Spielenation",facts:[["Nintendo","Nintendo, ursprünglich 1889 als Hersteller von Spielkarten gegründet, wurde erst im 20. Jahrhundert zum weltweit prägenden Videospiel-Unternehmen (Mario, Zelda, Pokémon)."],["Game Center","Game Center (ゲームセンター) — japanische Spielhallen — sind bis heute fester Bestandteil des Stadtbilds, oft über mehrere Stockwerke mit Arcade-Automaten, Kranspielen (UFO Catcher) und Foto-Automaten."],["Weitere Konsolenhersteller","Neben Nintendo prägten auch Sony (PlayStation) und Sega (u. a. Sonic, frühere eigene Konsolen) die globale Videospielbranche entscheidend mit."],["Pokémon","Die Pokémon-Reihe von Game Freak/Nintendo gilt gemessen am Gesamtumsatz über alle Medien hinweg als eine der wertvollsten Unterhaltungs-Marken der Welt."]],quiz:[{q:"Als was wurde Nintendo 1889 ursprünglich gegründet?",o:["Hersteller von Spielkarten","Videospiel-Studio","Automobilhersteller"],c:0},{q:'Was ist ein "Game Center" in Japan?',o:["Eine Spielhalle mit Arcade-Automaten","Ein Nintendo-Museum","Ein Online-Shop"],c:0},{q:"Welches Unternehmen steht hinter der PlayStation?",o:["Sony","Nintendo","Capcom"],c:0},{q:"Welche Reihe zählt zu den umsatzstärksten Unterhaltungs-Marken weltweit?",o:["Pokémon","Ausschließlich Filme","Reine Brettspiele"],c:0}]},{id:"pop-4",chapter:"Popkultur",title:"Fan-Kultur & Conventions",facts:[["Comiket","Comiket (Comic Market) in Tokyo ist mit oft über einer halben Million Besuchern pro Ausgabe eine der größten Fan-Messen der Welt, bekannt vor allem für selbstverlegte Dōjinshi."],["Dōjinshi","Dōjinshi sind selbst veröffentlichte Fan-Werke (oft Manga), die auf bestehenden Figuren und Welten aufbauen — eine große eigene Szene neben dem kommerziellen Verlagswesen."],["Akihabara","Der Tokyoter Stadtteil Akihabara gilt als Zentrum der Otaku-Kultur, mit unzähligen Läden für Anime, Manga, Videospiele und Sammelfiguren."],["Cosplay",'Cosplay (von "costume play") — das Verkleiden als Figuren aus Anime, Manga oder Videospielen — hat seine Wurzeln teils in Japan und ist heute weltweit auf Fan-Conventions verbreitet.']],quiz:[{q:"Wofür ist Comiket vor allem bekannt?",o:["Selbstverlegte Fan-Werke (Dōjinshi)","Ausschließlich Kochwettbewerbe","Automesse"],c:0},{q:"Was sind Dōjinshi?",o:["Selbstveröffentlichte Fan-Manga","Offizielle Verlagspublikationen","Zeitungen"],c:0},{q:"Welcher Tokyoter Stadtteil gilt als Zentrum der Otaku-Kultur?",o:["Akihabara","Ginza","Roppongi"],c:0},{q:'Woher stammt der Begriff "Cosplay"?',o:['Von "costume play"',"Von einem japanischen Eigennamen",'Von "cosmic play"'],c:0}]},{id:"pop-5",chapter:"Popkultur",title:"Musik: J-Pop, Idols & Enka",facts:[["Das Idol-System",'„Idols" sind durchgeplante, von Agenturen gemanagte Gesangsgruppen, die als Gesamtpaket vermarktet werden — mit häufigen Single-Veröffentlichungen, Fan-Events und Handshake-Terminen.'],["J-Pop","J-Pop ist aufwendig produzierter Mainstream-Pop. Der Heimatmarkt setzte lange stärker auf den Verkauf physischer CDs als auf Streaming."],["Enka","Enka ist ein sentimentaler Balladenstil mit einer festen Gesangs-Verzierung, verbunden mit älterem Publikum und dem Gefühl von Nostalgie."],["City Pop & Karaoke",'„City Pop", urbaner Pop der 1980er, erlebte Jahrzehnte später ein weltweites Online-Revival. Karaoke hält alte wie neue Lieder im Alltag lebendig.']],quiz:[{q:'Was beschreibt das „Idol"-System am besten?',o:["Durchgeplante, gemanagte Gesangsgruppen als Gesamtpaket","Klassische Sinfonieorchester","Spontane Straßenmusiker"],c:0},{q:"Was ist enka?",o:["Ein sentimentaler Balladenstil, oft für älteres Publikum","Elektronische Tanzmusik","Ein bäuerlicher Volkstanz"],c:0},{q:"Was war lange typisch für den japanischen Musikmarkt?",o:["Starker Verkauf physischer CDs","Ausschließlich Streaming","Kein kommerzieller Markt"],c:0},{q:'Was geschah mit „City Pop" aus den 1980ern?',o:["Jahrzehnte später ein weltweites Online-Revival","Es wurde landesweit verboten","Es blieb durchgehend auf Platz 1"],c:0}]},{id:"fest-1",chapter:"Feste & Feiertage",title:"Neujahr (Oshogatsu)",facts:[["Oshogatsu","Neujahr (お正月, Oshogatsu) ist das wichtigste Fest des japanischen Jahres — viele Betriebe schließen für mehrere Tage rund um den 1. Januar."],["Hatsumode","Beim Hatsumode (初詣) besucht man in den ersten Tagen des Jahres einen Schrein oder Tempel, um für Glück im neuen Jahr zu beten."],["Osechi-ryori","Osechi-ryori (おせち料理) sind kunstvoll geschichtete Neujahrsgerichte in Lackdosen, traditionell schon vor dem Jahreswechsel zubereitet, da an den ersten Tagen möglichst wenig gekocht wird."],["Otoshidama","Kinder bekommen zu Neujahr Geldgeschenke in kleinen Umschlägen, genannt Otoshidama (お年玉)."]],quiz:[{q:"Wie heißt der Neujahrs-Schreinbesuch auf Japanisch?",o:["Hatsumode","Hanami","Obon"],c:0},{q:"Was sind Osechi-ryori?",o:["Traditionelle Neujahrsgerichte","Ein Neujahrslied","Ein Feuerwerk"],c:0},{q:"Was ist Otoshidama?",o:["Geldgeschenke für Kinder zu Neujahr","Ein Neujahrsgruß-Brief","Ein Glücksbringer aus Papier"],c:0},{q:"Warum wird an den ersten Neujahrstagen traditionell wenig gekocht?",o:["Weil Osechi im Voraus zubereitet wird","Weil Restaurants gesetzlich geschlossen sein müssen","Weil Kochen als Unglück gilt"],c:0}]},{id:"fest-2",chapter:"Feste & Feiertage",title:"Sommerfeste",facts:[["Tanabata","Tanabata (七夕, Sternenfest) im Juli erinnert an die Legende zweier getrennter Liebender, Orihime und Hikoboshi, die sich nur einmal im Jahr treffen dürfen — Wünsche werden auf bunte Zettel geschrieben und an Bambuszweige gehängt."],["Obon","Obon (お盆) im Sommer ist ein buddhistisches Fest, bei dem der Ahnen gedacht wird — viele Menschen reisen in dieser Zeit in ihre Heimatorte, ähnlich wie an Neujahr."],["Bon Odori","Beim Bon Odori (盆踊り) tanzen Menschen gemeinsam auf Sommerfesten im Kreis um einen Turm — ursprünglich ein Willkommenstanz für die Geister der Verstorbenen."],["Hanabi Taikai","Feuerwerks-Festivals (花火大会, Hanabi Taikai) gehören zum festen Bestandteil des japanischen Sommers, oft besucht man sie im traditionellen Sommerkimono (Yukata)."]],quiz:[{q:"Worum geht es bei der Tanabata-Legende?",o:["Zwei getrennte Liebende, die sich einmal im Jahr treffen","Einen Drachen, der das Dorf beschützt","Die Gründung Japans"],c:0},{q:"Was ist Obon?",o:["Ein buddhistisches Ahnenfest im Sommer","Ein Neujahrsfest","Ein Sportfest"],c:0},{q:"Was passiert beim Bon Odori?",o:["Gemeinsamer Tanz im Kreis","Ein Umzug mit Wagen","Ein Feuerwerk"],c:0},{q:"Welches Kleidungsstück trägt man oft bei Sommerfesten?",o:["Yukata","Kimono aus Seide","Hakama"],c:0}]},{id:"fest-3",chapter:"Feste & Feiertage",title:"Herbst & Winter",facts:[["Shichi-Go-San",'Shichi-Go-San (七五三, "Sieben-Fünf-Drei") im November feiert das Heranwachsen von Mädchen im Alter von 3 und 7 sowie Jungen im Alter von 3 und 5 Jahren mit einem Schreinbesuch.'],["Tsukimi","Beim Mondfest Tsukimi (お月見) im Herbst wird der Vollmond bewundert, traditionell mit runden Reisklößchen (Tsukimi Dango) und Pampasgras als Dekoration."],["Weihnachten in Japan","Weihnachten ist in Japan kein gesetzlicher Feiertag und wird eher als romantisches Paar-Event gefeiert als als Familienfest — populär ist unter anderem der Brauch, an Heiligabend Fried Chicken zu essen."],["Omisoka","An Silvester (大晦日, Omisoka) isst man traditionell lange Buchweizennudeln (Toshikoshi Soba), die für ein langes Leben stehen sollen."]],quiz:[{q:"Für welche Altersgruppen wird Shichi-Go-San gefeiert?",o:["3, 5 und 7 Jahre","6, 12 und 18 Jahre","1 und 2 Jahre"],c:0},{q:"Was gehört traditionell zu Tsukimi?",o:["Reisklößchen und Pampasgras","Feuerwerk","Bunte Wunschzettel"],c:0},{q:"Wie wird Weihnachten in Japan meist gefeiert?",o:["Eher als Paar-Event, kein gesetzlicher Feiertag","Als großes Familienfest mit mehreren freien Tagen","Gar nicht begangen"],c:0},{q:"Welches Gericht isst man traditionell an Silvester?",o:["Toshikoshi Soba (Buchweizennudeln)","Sushi","Osechi-ryori"],c:0}]},{id:"fest-4",chapter:"Feste & Feiertage",title:"Nationale Feiertage im Überblick",facts:[["Golden Week",'Die "Golden Week" Ende April/Anfang Mai bündelt mehrere gesetzliche Feiertage kurz hintereinander und zählt zu den verkehrsreichsten Reisezeiten des Jahres.'],["Kaiserlicher Geburtstag","Der Geburtstag des amtierenden Tennō ist ein gesetzlicher Feiertag — das Datum ändert sich entsprechend mit jedem Thronwechsel."],["Anzahl Feiertage","Japan hat mit etwa 16 gesetzlichen Feiertagen pro Jahr im internationalen Vergleich recht viele arbeitsfreie Tage — steht trotzdem oft im Ruf einer sehr arbeitsintensiven Kultur."],["Happy Monday System",'Mehrere Feiertage wurden bewusst auf einen Montag gelegt ("Happy Monday System"), um lange Wochenenden zu ermöglichen.']],quiz:[{q:'Was ist die "Golden Week"?',o:["Eine Häufung gesetzlicher Feiertage Ende April/Anfang Mai","Ein Sommerfest","Der erste Schultag des Jahres"],c:0},{q:'Wovon hängt das Datum des "Kaiserlichen Geburtstags"-Feiertags ab?',o:["Vom Geburtsdatum des amtierenden Tennō","Es ist immer der 1. Januar","Es gibt diesen Feiertag nicht"],c:0},{q:'Was bezweckt das "Happy Monday System"?',o:["Lange Wochenenden durch auf Montag verlegte Feiertage","Mehr Feiertage im Dezember","Kürzere Arbeitswochen ganzjährig"],c:0},{q:"Wie viele gesetzliche Feiertage hat Japan ungefähr pro Jahr?",o:["Etwa 16","Etwa 5","Etwa 30"],c:0}]},{id:"wirt-1",chapter:"Wirtschaft & Arbeitswelt",title:"Wirtschaftswunder & Weltwirtschaft",facts:[["Nachkriegs-Wirtschaftswunder",'Nach der Zerstörung im Zweiten Weltkrieg erlebte Japan zwischen den 1950er- und 1980er-Jahren ein rasantes Wirtschaftswachstum, oft als "japanisches Wirtschaftswunder" bezeichnet.'],["Große Volkswirtschaft","Japan zählt gemessen am Bruttoinlandsprodukt zu den größten Volkswirtschaften der Welt und lag über Jahrzehnte lange auf Platz zwei hinter den USA."],["Exportstärke","Japan ist weltweit führend im Export von Autos und Präzisionstechnik — Marken wie Toyota, Honda und Sony stehen international für japanische Wertarbeit."],["Verlorene Dekade(n)",'Nach dem Platzen einer Immobilien- und Aktienblase Anfang der 1990er folgten mehrere Jahrzehnte wirtschaftlicher Stagnation, oft "verlorene Dekade(n)" genannt.']],quiz:[{q:"Wie wird Japans rasantes Wirtschaftswachstum nach dem Zweiten Weltkrieg oft genannt?",o:["Japanisches Wirtschaftswunder","Meiji-Restauration","Große Reform"],c:0},{q:"In welchen Bereichen ist Japan besonders exportstark?",o:["Autos und Präzisionstechnik","Landwirtschaft","Rohöl"],c:0},{q:"Was geschah Anfang der 1990er-Jahre?",o:["Eine Immobilien- und Aktienblase platzte","Japan trat der EU bei","Die Währung wurde abgeschafft"],c:0},{q:"Wie werden die wirtschaftlich stagnierenden Jahrzehnte danach oft genannt?",o:["Verlorene Dekade(n)","Goldenes Zeitalter","Zweites Wirtschaftswunder"],c:0}]},{id:"wirt-2",chapter:"Wirtschaft & Arbeitswelt",title:"Salaryman-Kultur",facts:[["Salaryman",'Der "Salaryman" (サラリーマン) — ein festangestellter Büroangestellter, meist im Anzug — gilt seit Jahrzehnten als Sinnbild des japanischen Arbeitslebens.'],["Lebenslange Anstellung",'Traditionell prägte das Konzept der "lebenslangen Anstellung" (終身雇用) große japanische Unternehmen — Angestellte blieben oft ihr gesamtes Berufsleben bei derselben Firma.'],["Nomikai","Gemeinsames Trinken nach der Arbeit (飲み会, Nomikai) gilt als wichtiger informeller Teil der Firmenkultur zur Beziehungspflege zwischen Kollegen."],["Karoshi",'Der Begriff Karoshi (過労死, "Tod durch Überarbeitung") entstand aus der Debatte um exzessive Überstunden und führte zu Reformen der Arbeitsgesetze.']],quiz:[{q:'Was bezeichnet der Begriff "Salaryman"?',o:["Einen festangestellten Büroangestellten","Einen selbstständigen Handwerker","Einen Landwirt"],c:0},{q:'Was beschreibt das Konzept "lebenslange Anstellung"?',o:["Bleiben bei derselben Firma über das ganze Berufsleben","Jährlicher Firmenwechsel","Arbeiten ohne festen Vertrag"],c:0},{q:"Was ist ein Nomikai?",o:["Gemeinsames Trinken nach der Arbeit","Eine Betriebsversammlung","Ein Bewerbungsgespräch"],c:0},{q:"Wofür steht der Begriff Karoshi?",o:["Tod durch Überarbeitung","Ein Firmenfest","Eine Beförderung"],c:0}]},{id:"wirt-3",chapter:"Wirtschaft & Arbeitswelt",title:"Große Konzerne (Keiretsu)",facts:[["Keiretsu","Keiretsu (系列) sind eng vernetzte Unternehmensgruppen mit gegenseitigen Beteiligungen und Geschäftsbeziehungen — ein prägendes Merkmal der japanischen Wirtschaftsstruktur."],["Zaibatsu-Vorgeschichte","Vor dem Zweiten Weltkrieg dominierten sogenannte Zaibatsu (財閥) — riesige Familienkonzerne wie Mitsubishi oder Mitsui — die japanische Wirtschaft; nach dem Krieg wurden sie unter alliierter Besatzung formal aufgelöst und entwickelten sich zu lockereren Keiretsu."],["Weltmarken","Zahlreiche global bekannte Marken stammen aus Japan, darunter Toyota, Nintendo, Panasonic, Canon und Uniqlo."],["Just-in-Time",'Das von Toyota entwickelte "Just-in-Time"-Produktionsprinzip, das Lagerbestände minimiert, gilt als einer der einflussreichsten japanischen Beiträge zur globalen Industrieproduktion.']],quiz:[{q:"Was sind Keiretsu?",o:["Eng vernetzte Unternehmensgruppen","Staatliche Behörden","Gewerkschaften"],c:0},{q:"Wie hießen die Vorgänger-Konzerne der Keiretsu vor dem Zweiten Weltkrieg?",o:["Zaibatsu","Shogunate","Daimyo"],c:0},{q:'Welches Unternehmen entwickelte das "Just-in-Time"-Prinzip?',o:["Toyota","Nintendo","Sony"],c:0},{q:"Welche der folgenden Marken stammt NICHT aus Japan?",o:["Samsung","Toyota","Canon"],c:0}]},{id:"wirt-4",chapter:"Wirtschaft & Arbeitswelt",title:"Wandel der Arbeitswelt",facts:[["Alternde Gesellschaft","Japans alternde und schrumpfende Bevölkerung führt in vielen Branchen zu spürbarem Arbeitskräftemangel."],["Work-Style-Reform",'Die "Work-Style-Reform"-Gesetze (働き方改革) von 2019 setzten erstmals verbindliche Obergrenzen für Überstunden, um exzessive Arbeitszeiten einzudämmen.'],["Frauen im Berufsleben",'Die Erwerbsquote von Frauen ist in den letzten Jahrzehnten deutlich gestiegen, auch als Teil politischer Programme zur Belebung der Wirtschaft ("Womenomics").'],["Zunehmende Flexibilität","Konzepte wie Telearbeit und flexiblere Vertragsformen gewinnen an Bedeutung, auch wenn die traditionelle Festanstellung weiterhin verbreitet ist."]],quiz:[{q:"Was ist eine zentrale wirtschaftliche Herausforderung durch Japans Bevölkerungsentwicklung?",o:["Arbeitskräftemangel durch alternde Gesellschaft","Zu viele junge Arbeitskräfte","Kein Einfluss auf die Wirtschaft"],c:0},{q:'Was regelten die "Work-Style-Reform"-Gesetze von 2019?',o:["Verbindliche Obergrenzen für Überstunden","Die Einführung der Vier-Tage-Woche für alle","Ein Verbot von Teilzeitarbeit"],c:0},{q:'Was bezeichnet der Begriff "Womenomics"?',o:["Politische Programme zur Förderung von Frauen im Berufsleben","Eine reine Frauenbank","Ein Modelabel"],c:0},{q:"Welcher Trend gewinnt neben der traditionellen Festanstellung an Bedeutung?",o:["Telearbeit und flexiblere Vertragsformen","Ausschließlich Schichtarbeit","Kinderarbeit"],c:0}]},{id:"wirt-5",chapter:"Wirtschaft & Arbeitswelt",title:"Landwirtschaft, Fischerei & Ernährung",facts:[["Kleinbäuerlich & geschützt","Japans Höfe sind klein, der Reisanbau ist mit Zöllen und Subventionen politisch geschützt. Die Bauern sind im Schnitt alt, Nachfolger fehlen."],["Selbstversorgung","Der Selbstversorgungsgrad bei Nahrung liegt kalorienbasiert bei rund 38 % — eine wiederkehrende politische Sorge angesichts der Abhängigkeit von Importen."],["Fischnation","Japan gehört zu den größten Fischkonsumenten pro Kopf. Der Großmarkt in Toyosu (früher Tsukiji) in Tokyo ist weltweit ein Bezugspunkt; der Walfang bleibt international umstritten."],["Markenprodukte","Ein großer Teil des Werts steckt in hochpreisigen Markenprodukten — Wagyū-Rind, Premium-Obst (etwa Geschenk-Melonen), regionaler Reis und Tee."]],quiz:[{q:"Wie ist die japanische Landwirtschaft überwiegend strukturiert?",o:["Viele kleine, oft alternde Betriebe","Wenige sehr große Farmen","Rein industrielle Massenbetriebe"],c:0},{q:"Wie hoch ist Japans Selbstversorgungsgrad bei Nahrung (kalorienbasiert) etwa?",o:["Rund 38 %","Über 90 %","Genau 100 %"],c:0},{q:"Wofür ist der Markt in Toyosu (früher Tsukiji) bekannt?",o:["Als weltbekannter Fischgroßmarkt","Als Gebrauchtwagenbörse","Als Blumengroßmarkt"],c:0},{q:"Was ist ein Beispiel für hochpreisige japanische Markenprodukte?",o:["Wagyū-Rind und Premium-Obst","Tiefkühlpizza","Instant-Nudeln"],c:0}]},{id:"pol-1",chapter:"Politik & Gesellschaftssystem",title:"Staatsform & Verfassung",facts:[["Konstitutionelle Monarchie",'Japan ist eine parlamentarische, konstitutionelle Monarchie — der Tennō (Kaiser) ist Staatsoberhaupt ohne politische Macht, rein symbolisch als "Symbol des Staates und der Einheit des Volkes".'],["Nachkriegsverfassung","Die heutige Verfassung trat 1947 unter alliierter Besatzung in Kraft und ersetzte die Meiji-Verfassung von 1889."],["Artikel 9","Artikel 9 der Verfassung verzichtet auf Krieg als Mittel der Staatspolitik — eine zentrale und bis heute politisch diskutierte Grundlage der japanischen Nachkriegsordnung."],["Älteste erbliche Monarchie","Die japanische Kaiserfamilie gilt als eine der ältesten noch bestehenden erblichen Monarchien der Welt, mit einer traditionellen Herrscherlinie, die weit in die Frühgeschichte zurückreicht."]],quiz:[{q:"Welche Staatsform hat Japan?",o:["Parlamentarische, konstitutionelle Monarchie","Präsidialrepublik","Absolute Monarchie"],c:0},{q:"Wann trat die heutige japanische Verfassung in Kraft?",o:["1947","1868","1989"],c:0},{q:"Worauf verzichtet Artikel 9 der Verfassung?",o:["Krieg als Mittel der Staatspolitik","Das Wahlrecht","Die Pressefreiheit"],c:0},{q:"Welche Rolle hat der Tennō laut Verfassung?",o:["Symbolisches Staatsoberhaupt ohne politische Macht","Regierungschef mit vollen Machtbefugnissen","Oberbefehlshaber des Militärs"],c:0}]},{id:"pol-2",chapter:"Politik & Gesellschaftssystem",title:"Parlament & Regierung",facts:[["Kokkai","Das japanische Parlament, Kokkai (国会), besteht aus zwei Kammern: dem Repräsentantenhaus und dem Councillors-Haus (Oberhaus)."],["Premierminister","Der Premierminister wird vom Parlament aus seiner Mitte gewählt und ist Regierungschef — anders als der Tennō mit realer politischer Macht ausgestattet."],["LDP","Die Liberaldemokratische Partei (LDP) hat seit ihrer Gründung 1955 die meiste Zeit die Regierung gestellt und prägt die japanische Nachkriegspolitik entscheidend."],["Wahlrecht","Das aktive Wahlrecht liegt bei 18 Jahren; Wahlen zum Unterhaus finden spätestens alle vier Jahre statt, können aber vom Premierminister früher angesetzt werden."]],quiz:[{q:"Wie heißt das japanische Parlament?",o:["Kokkai","Shogunat","Daimyo-Rat"],c:0},{q:"Wie wird der japanische Premierminister bestimmt?",o:["Vom Parlament aus seiner Mitte gewählt","Vom Tennō ernannt ohne Wahl","Direkt vom Volk gewählt"],c:0},{q:"Welche Partei stellte seit 1955 meist die Regierung?",o:["Liberaldemokratische Partei (LDP)","Kommunistische Partei","Grüne Partei"],c:0},{q:"Ab welchem Alter gilt in Japan das aktive Wahlrecht?",o:["18 Jahre","21 Jahre","16 Jahre"],c:0}]},{id:"pol-3",chapter:"Politik & Gesellschaftssystem",title:"Verwaltung & Rechtssystem",facts:[["47 Präfekturen","Japan gliedert sich in 47 Präfekturen, jede mit eigenem gewählten Gouverneur und eigener Präfekturversammlung."],["Tokio als Sonderfall",'Tokio ist keine gewöhnliche Stadt, sondern eine eigene Präfektur ("Tokyo-to"), unterteilt in 23 besondere Bezirke mit eigenen Verwaltungen.'],["Rechtssystem","Das japanische Rechtssystem basiert überwiegend auf kontinentaleuropäischem (v. a. deutschem und französischem) Zivilrecht, mit Wurzeln in der Zeit der Meiji-Modernisierung."],["Saiban-in","Seit 2009 wirken bei bestimmten schweren Strafprozessen Laienrichter (裁判員, Saiban-in) gemeinsam mit Berufsrichtern am Urteil mit — ähnlich einem Schöffensystem."]],quiz:[{q:"In wie viele Präfekturen gliedert sich Japan?",o:["47","8","100"],c:0},{q:"Was ist an Tokios Verwaltungsstatus besonders?",o:["Es ist selbst eine Präfektur mit 23 besonderen Bezirken","Es hat keinerlei eigene Verwaltung","Es gehört zu Osaka"],c:0},{q:"Auf welcher Rechtstradition basiert das japanische Rechtssystem überwiegend?",o:["Kontinentaleuropäisches Zivilrecht","Britisches Common Law","Islamisches Recht"],c:0},{q:"Was ist Saiban-in?",o:["Ein Laienrichter-System bei schweren Strafprozessen","Ein Verkehrsgesetz","Eine Steuerbehörde"],c:0}]},{id:"pol-4",chapter:"Politik & Gesellschaftssystem",title:"Internationale Rolle",facts:[["US-japanisches Sicherheitsbündnis","Seit 1951/1960 besteht ein Sicherheitsbündnis mit den USA, das bis heute die Grundlage der japanischen Außen- und Verteidigungspolitik bildet."],["Selbstverteidigungsstreitkräfte","Statt regulärer Streitkräfte unterhält Japan die Selbstverteidigungsstreitkräfte (自衛隊, Jieitai) — offiziell auf Verteidigung beschränkt, ihre genaue verfassungsrechtliche Einordnung wird bis heute diskutiert."],["UN-Mitgliedschaft","Japan trat 1956 den Vereinten Nationen bei und zählt seither zu den größten Beitragszahlern des UN-Budgets."],["G7-Mitglied","Japan ist das einzige asiatische Mitglied der G7, der Gruppe der sieben führenden Industrienationen."]],quiz:[{q:"Mit welchem Land besteht seit den 1950ern ein zentrales Sicherheitsbündnis Japans?",o:["USA","China","Russland"],c:0},{q:"Wie heißen Japans Streitkräfte offiziell?",o:["Selbstverteidigungsstreitkräfte (Jieitai)","Kaiserliche Armee","Nationalgarde"],c:0},{q:"Wann trat Japan den Vereinten Nationen bei?",o:["1956","1945","1990"],c:0},{q:"In welcher internationalen Ländergruppe ist Japan das einzige asiatische Mitglied?",o:["G7","BRICS","EU"],c:0}]},{id:"bild-1",chapter:"Bildungssystem",title:"Schulsystem im Überblick",facts:[["Schulpflicht","Die Schulpflicht in Japan umfasst neun Jahre: sechs Jahre Grundschule (Shogakko) und drei Jahre Mittelschule (Chugakko)."],["Oberschule freiwillig, aber üblich","Der Besuch der dreijährigen Oberschule (Koko) ist offiziell freiwillig, wird aber von der überwiegenden Mehrheit der Jugendlichen durchlaufen."],["Schuljahresbeginn im April","Das japanische Schul- und Geschäftsjahr beginnt traditionell im April, nicht im Herbst wie in vielen anderen Ländern — passend zur Kirschblütensaison."],["Hohe Alphabetisierung","Japan zählt mit einer Alphabetisierungsrate von nahezu 100 % zu den Ländern mit der höchsten Grundbildung weltweit."]],quiz:[{q:"Wie viele Jahre umfasst die Schulpflicht in Japan?",o:["Neun Jahre","Sechs Jahre","Zwölf Jahre"],c:0},{q:"Wann beginnt traditionell das japanische Schuljahr?",o:["Im April","Im September","Im Januar"],c:0},{q:"Ist der Besuch der Oberschule (Koko) in Japan gesetzlich verpflichtend?",o:["Nein, aber von den meisten besucht","Ja, verpflichtend wie die Mittelschule","Nein, komplett unüblich"],c:0},{q:"Wie hoch ist die Alphabetisierungsrate in Japan ungefähr?",o:["Nahezu 100 %","Etwa 70 %","Etwa 50 %"],c:0}]},{id:"bild-2",chapter:"Bildungssystem",title:"Prüfungsdruck & Juken",facts:[["Juken",'Aufnahmeprüfungen (受験, Juken) für weiterführende Schulen und Universitäten gelten als entscheidende Weichenstellung für die spätere Karriere — der intensive Vorbereitungsdruck wird umgangssprachlich "Prüfungshölle" (受験地獄, Juken Jigoku) genannt.'],["Juku","Viele Schüler besuchen zusätzlich zum regulären Unterricht private Nachhilfeschulen (塾, Juku), oft bis in den späten Abend."],["Zentrale Aufnahmeprüfung","Für den Hochschulzugang existiert eine landesweit einheitliche Aufnahmeprüfung, die neben hochschulspezifischen Zusatzprüfungen über die Zulassung mitentscheidet."],["Rangfolge der Universitäten","Der Ruf einer Universität — etwa der Universität Tokyo als renommierteste des Landes — spielt bei Bewerbungen und der späteren Jobsuche traditionell eine große Rolle."]],quiz:[{q:'Was bedeutet "Juken Jigoku"?',o:['"Prüfungshölle", der intensive Vorbereitungsdruck vor Aufnahmeprüfungen',"Ein Schulfach","Ein Feiertag"],c:0},{q:"Was ist ein Juku?",o:["Eine private Nachhilfeschule","Eine Sportart","Ein Schulausflug"],c:0},{q:"Wofür gibt es in Japan eine landesweit einheitliche Prüfung?",o:["Für den Hochschulzugang","Für den Führerschein","Für die Einbürgerung"],c:0},{q:"Welche Universität gilt traditionell als renommierteste Japans?",o:["Universität Tokyo","Universität Osaka","Universität Kyoto"],c:0}]},{id:"bild-3",chapter:"Bildungssystem",title:"Schulalltag & Besonderheiten",facts:[["Seifuku","An den meisten weiterführenden Schulen sind Schuluniformen (制服, Seifuku) Pflicht — oft im klassischen Matrosen- oder Blazer-Stil."],["Souji","Schüler reinigen ihre Klassenräume und Schulgebäude selbst (掃除, Souji), statt dass dafür externes Reinigungspersonal zuständig ist — als Teil der Erziehung zu Verantwortung und Gemeinschaftssinn."],["Kyushoku","Das gemeinsame Schulmittagessen (給食, Kyushoku) wird oft von den Schülern selbst im Klassenzimmer ausgeteilt und gemeinsam mit der Lehrkraft eingenommen."],["Bukatsu","Nachmittägliche Klub-Aktivitäten (部活, Bukatsu) — von Sport bis Musik — sind fester Bestandteil des Schullebens und oft zeitintensiver als in vielen anderen Ländern."]],quiz:[{q:"Was ist Souji im Schulkontext?",o:["Die Reinigung der Schule durch die Schüler selbst","Ein Sportfest","Eine Mahlzeit"],c:0},{q:"Was ist Kyushoku?",o:["Das gemeinsame Schulmittagessen","Eine Prüfung","Ein Schulausflug"],c:0},{q:"Was sind Bukatsu?",o:["Nachmittägliche Klub-Aktivitäten","Hausaufgaben","Elternabende"],c:0},{q:"Wie sind Schuluniformen an den meisten weiterführenden Schulen geregelt?",o:["Meist Pflicht","Generell verboten","Nur an Sonntagen getragen"],c:0}]},{id:"bild-4",chapter:"Bildungssystem",title:"Universitäten & Weiterbildung",facts:[["Vierjähriges Studium","Ein reguläres Universitätsstudium (Bachelor, 学士) dauert in Japan meist vier Jahre, medizinische Fächer oft länger."],["Zügiger Abschluss als Norm","Ein Studienabschluss ohne größere Verzögerung gilt gesellschaftlich als Erwartung, auch weil sich viele Firmen an einem festen Berufseinstiegs-Zeitpunkt orientieren."],["Shushoku Katsudo","Die Jobsuche (就職活動, Shushoku Katsudo) beginnt bei vielen Studierenden bereits ein bis zwei Jahre vor dem Abschluss, mit einem stark standardisierten Bewerbungsprozess."],["Lebenslanges Lernen","Angesichts einer alternden Gesellschaft gewinnen Weiterbildungsangebote für Erwachsene und Senioren zunehmend an Bedeutung, etwa an volkshochschulähnlichen Einrichtungen (Karuchā Sentā)."]],quiz:[{q:"Wie lange dauert ein reguläres Bachelorstudium in Japan meist?",o:["Vier Jahre","Zwei Jahre","Sechs Jahre"],c:0},{q:"Was ist Shushoku Katsudo?",o:["Der stark standardisierte Prozess der Jobsuche vor dem Abschluss","Ein Universitätsfach","Ein Studentenwohnheim"],c:0},{q:"Warum orientieren sich viele Studierende an einem zügigen Studienabschluss?",o:["Weil Firmen oft feste Berufseinstiegs-Zeitpunkte haben","Weil längeres Studium gesetzlich verboten ist","Weil es keine Studiengebühren gibt"],c:0},{q:"Was gewinnt angesichts der alternden Gesellschaft zunehmend an Bedeutung?",o:["Weiterbildungsangebote für Erwachsene und Senioren","Ausschließlich Grundschulbildung","Privatunterricht für Kleinkinder"],c:0}]},{id:"kat-1",chapter:"Umgang mit Naturkatastrophen",title:"Erdbebenkultur & Vorsorge",facts:[["Pazifischer Feuerring","Japan liegt auf dem Pazifischen Feuerring und erlebt jährlich tausende, meist sehr schwache, Erdbeben — spürbare Beben gehören für viele Menschen zum Alltag."],["Strenge Bauvorschriften","Seit den 1980er-Jahren gelten in Japan besonders strenge erdbebensichere Bauvorschriften, die seither mehrfach weiter verschärft wurden."],["Katastrophenschutztag","An Schulen und in Unternehmen finden regelmäßig Erdbeben- und Evakuierungsübungen statt, oft am landesweiten Katastrophenschutztag (1. September)."],["Bosai Rukku","Viele Haushalte halten einen gepackten Notfallrucksack (防災リュック, Bosai Rukku) mit Wasser, Lebensmitteln und Erste-Hilfe-Material bereit."]],quiz:[{q:"Warum erlebt Japan besonders viele Erdbeben?",o:["Es liegt auf dem Pazifischen Feuerring","Es liegt mitten auf einem Kontinent","Reiner Zufall ohne geologischen Grund"],c:0},{q:"Seit wann gelten besonders strenge erdbebensichere Bauvorschriften?",o:["Seit den 1980er-Jahren","Erst seit 2020","Es gibt keine besonderen Vorschriften"],c:0},{q:"Wann findet der landesweite japanische Katastrophenschutztag statt?",o:["1. September","1. Januar","24. Dezember"],c:0},{q:"Was ist ein Bosai Rukku?",o:["Ein gepackter Notfallrucksack","Ein Erdbebenmelder","Eine Behörde"],c:0}]},{id:"kat-2",chapter:"Umgang mit Naturkatastrophen",title:"Frühwarnsysteme",facts:[["Erdbebenfrühwarnsystem","Japans Erdbebenfrühwarnsystem kann oft wenige Sekunden bis über eine Minute vor den stärksten Erschütterungen warnen — genug Zeit, um Züge zu bremsen oder in Deckung zu gehen."],["J-Alert","Über das landesweite J-Alert-System werden Warnungen zu Erdbeben, Tsunamis und anderen Gefahren direkt auf Mobiltelefone sowie über Lautsprecher im öffentlichen Raum verbreitet."],["Tsunami-Warnstufen","Die japanische Wetterbehörde stuft Tsunami-Warnungen in mehrere Schweregrade ein, von einer einfachen Beobachtungsmeldung bis zur Großwarnung."],["Evakuierungstürme","In tsunamigefährdeten Küstenregionen wurden nach 2011 zahlreiche Evakuierungstürme und -gebäude errichtet, die im Notfall schnell Schutz auf höherem Gelände bieten sollen."]],quiz:[{q:"Wofür wird das Erdbebenfrühwarnsystem genutzt?",o:["Um kurz vor starken Erschütterungen zu warnen","Um das Wetter vorherzusagen","Um Verkehrsstaus zu melden"],c:0},{q:"Was ist J-Alert?",o:["Ein landesweites Warnsystem für Katastrophen","Eine Nachrichten-App ohne amtlichen Bezug","Ein Wetterdienst nur für Tokio"],c:0},{q:"Wie werden Tsunami-Warnungen in Japan eingestuft?",o:["In mehrere Schweregrade",'Nur als "Warnung" oder "keine Warnung"',"Es gibt kein Stufensystem"],c:0},{q:"Wozu dienen die nach 2011 gebauten Evakuierungstürme?",o:["Schnellen Schutz auf höherem Gelände bei Tsunami-Gefahr","Als Aussichtstürme für Touristen","Als reine Funkmasten"],c:0}]},{id:"kat-3",chapter:"Umgang mit Naturkatastrophen",title:"Tōhoku 2011 — ein Wendepunkt",facts:[["Tōhoku-Erdbeben","Am 11. März 2011 erschütterte eines der stärksten je gemessenen Erdbeben die Region Tōhoku und löste einen verheerenden Tsunami aus."],["Auswirkungen","Die Katastrophe forderte zehntausende Todesopfer und zerstörte weite Küstenabschnitte — eine der folgenreichsten Naturkatastrophen der jüngeren japanischen Geschichte."],["Fukushima","Der Tsunami verursachte zudem einen schweren Unfall im Kernkraftwerk Fukushima Daiichi, der zu großräumigen Evakuierungen und einer bis heute andauernden Debatte über Atomenergie in Japan führte."],["Lehren für die Vorsorge","Nach 2011 wurden Frühwarnsysteme, Deichanlagen und Evakuierungspläne in vielen Küstenregionen grundlegend überarbeitet."]],quiz:[{q:"Wann ereignete sich das große Tōhoku-Erdbeben?",o:["11. März 2011","1. September 1995","Neujahr 2000"],c:0},{q:"Was löste das Erdbeben zusätzlich aus?",o:["Einen verheerenden Tsunami","Einen Vulkanausbruch","Eine Dürreperiode"],c:0},{q:"Welches Kraftwerk war vom Unfall in Folge des Tsunamis betroffen?",o:["Fukushima Daiichi","Kashiwazaki-Kariwa","Ohi"],c:0},{q:"Was wurde nach 2011 in vielen Küstenregionen überarbeitet?",o:["Frühwarnsysteme, Deiche und Evakuierungspläne","Ausschließlich die Fischereigesetze","Nichts, es blieb alles unverändert"],c:0}]},{id:"kat-4",chapter:"Umgang mit Naturkatastrophen",title:"Katastrophenschutz im Alltag",facts:[["Hinanjo","Schulen und andere öffentliche Gebäude sind oft offiziell als Evakuierungsorte (避難所, Hinanjo) ausgewiesen und entsprechend beschildert."],["Katastrophenschutz-Apps","Zahlreiche Apps und Dienste liefern in Echtzeit Informationen zu Erdbeben, Wetterwarnungen und Evakuierungsanweisungen, oft mehrsprachig für internationale Besucher."],["Notfallkarten","In vielen Haushalten hängt eine von der Stadtverwaltung verteilte Notfallkarte mit lokalen Fluchtwegen und Sammelpunkten aus."],["Jichikai","Nachbarschaftsvereine (自治会, Jichikai) organisieren oft lokale Übungen und Vorräte für den Katastrophenfall — Vorsorge gilt stark als Gemeinschaftsaufgabe, nicht nur als individuelle Verantwortung."]],quiz:[{q:"Was ist ein Hinanjo?",o:["Ein offiziell ausgewiesener Evakuierungsort","Ein Erdbebenmuseum","Ein Feiertag"],c:0},{q:"Wofür werden viele Katastrophenschutz-Apps in Japan genutzt?",o:["Echtzeit-Informationen zu Erdbeben und Evakuierung","Ausschließlich für Verkehrsnachrichten","Nur für Restaurantbewertungen"],c:0},{q:"Wer verteilt oft Notfallkarten mit lokalen Fluchtwegen?",o:["Die Stadtverwaltung","Private Werbefirmen","Niemand, sie existieren nicht"],c:0},{q:"Was organisieren Nachbarschaftsvereine (Jichikai) oft mit?",o:["Lokale Katastrophenschutzübungen und Vorräte","Ausschließlich Sportfeste","Musikkonzerte"],c:0}]},{id:"region-1",chapter:"Regionale Unterschiede",title:"Kantō gegen Kansai",facts:[["Zwei Pole","Kantō um Tōkyō gilt als nüchtern und tempoorientiert, Kansai um Ōsaka/Kyōto als direkter, humorvoller und stolz auf die eigene Sprache."],["Rolltreppe","In Tōkyō stellt man sich links, in Ōsaka rechts — eine der bekanntesten Alltagsdifferenzen."],["Küche","Kansai-Dashi ist heller und milder, Kantō-Brühe dunkler und sojalastiger; sogar Fertig-Instantnudeln gibt es in Ost- und West-Varianten."],["Selbstbild","Ōsaka pflegt ein Image als Gegenentwurf zur Hauptstadt: Handelsstadt, Comedy (manzai), lautere Geselligkeit."]],quiz:[{q:"Wo stellt man sich auf der Rolltreppe rechts hin?",o:["Ōsaka","Tōkyō","Sapporo"],c:0},{q:"Wie gilt die Kansai-Brühe im Vergleich zu Kantō?",o:["heller und milder","dunkler und salziger","identisch"],c:0},{q:"Wofür ist Ōsaka als Selbstbild bekannt?",o:["Handel und Comedy","Regierungssitz","Autoindustrie"],c:0}]},{id:"region-2",chapter:"Regionale Unterschiede",title:"Tōhoku & Hokkaidō — der Norden",facts:[["Tōhoku","Der Nordosten Honshūs ist dünn besiedelt, landwirtschaftlich geprägt (Reis, Äpfel) und für schneereiche Winter sowie einen als zurückhaltend geltenden Menschenschlag bekannt."],["2011","Das Tōhoku-Erdbeben und der Tsunami vom 11. März 2011 mit der Reaktorkatastrophe von Fukushima prägen die Region bis heute."],["Hokkaidō","Die Nordinsel wurde erst ab 1869 systematisch von Japan besiedelt; das Straßenraster von Sapporo und Farmen nach US-Vorbild erinnern daran."],["Klima & Küche","Hokkaidō liefert Milchprodukte, Meeresfrüchte und Miso-Ramen; das Schneefestival von Sapporo zieht Millionen an."]],quiz:[{q:"Wann begann die systematische Besiedlung Hokkaidōs durch Japan?",o:["ab 1869","im 8. Jahrhundert","nach 1945"],c:0},{q:"Wofür ist Tōhoku landwirtschaftlich bekannt?",o:["Reis und Äpfel","Zitrusfrüchte und Wein","Tee und Zuckerrohr"],c:0},{q:"Welches Ereignis prägt Tōhoku seit 2011?",o:["Erdbeben, Tsunami und Fukushima","eine Weltausstellung","die Öffnung des Shinkansen"],c:0}]},{id:"region-3",chapter:"Regionale Unterschiede",title:"Kyūshū — das Tor nach Süden",facts:[["Lage","Die südwestlichste Hauptinsel liegt näher an Seoul und Shanghai als an Tōkyō und war historisch Japans Kontaktzone nach Asien und Europa."],["Nagasaki","Über die künstliche Insel Dejima lief in der Abschließungszeit (Sakoku) der einzige geregelte Handel mit Europäern (Niederländer)."],["Vulkane","Kyūshū ist stark vulkanisch: der Aso zählt zu den größten Calderen der Welt, der Sakurajima bei Kagoshima ist quasi dauernd aktiv."],["Onsen","Beppu und Yufuin gehören zu den ergiebigsten Thermalquellen-Orten des Landes."]],quiz:[{q:"Worüber lief in der Abschließungszeit der Europa-Handel?",o:["die Insel Dejima bei Nagasaki","den Hafen von Tōkyō","Sapporo"],c:0},{q:"Was ist der Aso?",o:["eine der größten Calderen der Welt","ein Bahnhof","ein Festival"],c:0},{q:"Geografisch liegt Kyūshū …",o:["nahe an Korea und China","nördlich von Hokkaidō","mitten im Pazifik"],c:0}]},{id:"region-4",chapter:"Regionale Unterschiede",title:"Okinawa & die Ryūkyū-Kultur",facts:[["Eigenes Königreich","Bis 1879 war das Ryūkyū-Königreich ein eigenständiger, tributpflichtiger Staat mit engen Beziehungen zu China; erst dann wurde es als Präfektur Okinawa annektiert."],["Sprache & Kultur","Die Ryūkyū-Sprachen sind mit dem Japanischen verwandt, aber nicht gegenseitig verständlich; Musik (sanshin), Tanz und Küche unterscheiden sich deutlich."],["1945","Die Schlacht um Okinawa war die verlustreichste des Pazifikkriegs auf japanischem Boden; ein großer Teil der Zivilbevölkerung starb."],["US-Basen","Okinawa trägt bis heute einen überproportionalen Anteil der US-Militärpräsenz in Japan, was regelmäßig zu Protesten und Konflikten führt."]],quiz:[{q:"Bis wann bestand das Ryūkyū-Königreich?",o:["bis 1879","bis 1945","bis 1603"],c:0},{q:"Wie verhalten sich Ryūkyū-Sprachen zum Japanischen?",o:["verwandt, aber nicht gegenseitig verständlich","identisch","völlig unverwandt"],c:0},{q:"Was ist auf Okinawa bis heute ein Konfliktthema?",o:["der hohe Anteil an US-Basen","ein Fischereiverbot","die Zeitzone"],c:0}]},{id:"region-5",chapter:"Regionale Unterschiede",title:"Dialekte und Standardsprache",facts:[["Hyōjungo","Die Standardsprache (hyōjungo) beruht auf dem Tōkyōer Sprachgebrauch und wurde ab der Meiji-Zeit über Schule und Rundfunk verbreitet."],["Kansai-ben","Der Kansai-Dialekt ist der bekannteste: eigene Kopula (や statt だ), eigene Betonung, in Comedy und Fernsehen sehr präsent."],["Vielfalt","Manche Dialekte — etwa in Tōhoku oder auf Okinawa — sind für andere Japaner ohne Übung kaum verständlich."],["Alltag","Viele Menschen wechseln situativ zwischen Dialekt (privat, regional) und Standardsprache (Beruf, Fremde) — eine Form von Code-Switching."]],quiz:[{q:"Worauf beruht die japanische Standardsprache?",o:["dem Tōkyōer Sprachgebrauch","dem Kyōto-Hofjapanisch","dem Okinawa-Dialekt"],c:0},{q:"Welche Kopula nutzt der Kansai-Dialekt statt だ?",o:["や","ね","さ"],c:0},{q:'Was ist mit „situativem Wechsel" gemeint?',o:["Code-Switching zwischen Dialekt und Standard","Sprachverbot","zweisprachige Schulen"],c:0}]},{id:"div-1",chapter:"Vielfalt & Minderheiten",title:"Die Ainu — Ureinwohner Hokkaidōs",facts:[["Wer","Die Ainu sind die indigene Bevölkerung Hokkaidōs, der Kurilen und Sachalins mit eigener Sprache, Religion (Kamuy-Glaube) und mündlicher Dichtung (yukar)."],["Assimilation","Ab 1869 verboten Gesetze Sprache, Jagd und Bräuche weitgehend und drängten die Ainu zur Anpassung; die Sprache gilt heute als stark gefährdet."],["Anerkennung","Erst 2008 erkannte das Parlament die Ainu offiziell als indigenes Volk an; 2019 folgte ein Gesetz gegen Diskriminierung und zur Kulturförderung."],["Heute","Zahlen sind unsicher (Schätzungen: mehrere Zehntausend mit Ainu-Wurzeln); das Kulturzentrum Upopoy bei Shiraoi eröffnete 2020."]],quiz:[{q:"Wann erkannte Japan die Ainu offiziell als indigenes Volk an?",o:["2008","1946","1972"],c:0},{q:"Woher stammen die Ainu?",o:["Hokkaidō, Kurilen, Sachalin","Okinawa","Kyūshū"],c:0},{q:"Wie ist der Zustand der Ainu-Sprache?",o:["stark gefährdet","Amtssprache","weit verbreitet"],c:0}]},{id:"div-2",chapter:"Vielfalt & Minderheiten",title:"Zainichi — Koreaner in Japan",facts:[["Herkunft","Viele Zainichi-Koreaner stammen von Menschen ab, die während der Kolonialzeit (1910–1945) nach Japan kamen oder gebracht wurden."],["Staatsangehörigkeit",'Nach 1952 verloren sie die japanische Staatsangehörigkeit; bis heute leben viele als „special permanent residents" mit koreanischem Pass, andere sind eingebürgert.'],["Alltag","Diskriminierung bei Wohnung, Arbeit und Heirat war lange verbreitet; viele nutzen einen japanischen Alltagsnamen (tsūmei)."],["Gemeinschaft","Es gibt zwei große Dachverbände (mit Bezug zu Süd- bzw. Nordkorea), eigene Schulen und ein reiches kulturelles Leben, etwa in Ōsakas Ikuno-Viertel."]],quiz:[{q:"Aus welcher Zeit stammt die Zuwanderung vieler Zainichi-Vorfahren?",o:["der Kolonialzeit 1910–1945","den 1990ern","der Edo-Zeit"],c:0},{q:'Was ist ein „tsūmei"?',o:["ein japanischer Alltagsname","ein Visum","eine Schule"],c:0},{q:"Welchen Aufenthaltsstatus haben viele Zainichi?",o:["special permanent resident","Touristenvisum","Diplomatenstatus"],c:0}]},{id:"div-3",chapter:"Vielfalt & Minderheiten",title:"Burakumin — eine unsichtbare Ausgrenzung",facts:[["Ursprung",'In der Ständeordnung der Edo-Zeit galten Menschen in „unreinen" Berufen (Schlachten, Gerben, Bestattung) als Ausgestoßene; ihre Nachfahren nennt man burakumin.'],["Formell abgeschafft","Die Standesgrenzen wurden 1871 aufgehoben, doch soziale Ausgrenzung bei Heirat und Anstellung hielt sich über Herkunftsorte und alte Register."],["Bewegung","Die Buraku-Befreiungsbewegung erkämpfte ab dem 20. Jahrhundert staatliche Förderprogramme für betroffene Stadtviertel (bis 2002)."],["Heute",'Die Diskriminierung ist rechtlich verboten und im Alltag zurückgegangen, aber „Hintergrund-Checks" und Online-Listen bleiben ein Thema.']],quiz:[{q:"Worauf geht die Burakumin-Ausgrenzung zurück?",o:['„unreine" Berufe in der Ständeordnung',"eine andere Sprache","eine Religion"],c:0},{q:"Wann wurden die Standesgrenzen formell aufgehoben?",o:["1871","1945","1603"],c:0},{q:"Womit hält sich Diskriminierung teils bis heute?",o:["Herkunftsorte und alte Register","Sprachtests","Kleiderordnung"],c:0}]},{id:"div-4",chapter:"Vielfalt & Minderheiten",title:"Ausländische Bevölkerung & Migration",facts:[["Anteil","Rund 3 Millionen Menschen ohne japanische Staatsangehörigkeit leben im Land (etwa 2–3 %) — größte Gruppen: China, Vietnam, Südkorea, Philippinen, Brasilien."],["Nikkei",'Ab 1990 holte Japan Nachfahren japanischer Auswanderer aus Brasilien und Peru („Nikkei") für die Industrie; viele blieben dauerhaft.'],["Arbeitskräfte",'Programme wie das „Technical Intern Training" und ab 2019 „Specified Skilled Worker" decken den Bedarf in Pflege, Bau, Landwirtschaft und Gastronomie.'],["Debatte","Offiziell versteht sich Japan nicht als Einwanderungsland; faktisch steigt die Zuwanderung, und Integration, Sprache und Rechte werden zunehmend diskutiert."]],quiz:[{q:'Wer sind die „Nikkei", die ab 1990 angeworben wurden?',o:["Nachfahren japanischer Auswanderer in Südamerika","Austauschstudenten aus den USA","chinesische Touristen"],c:0},{q:"Wie hoch ist der Anteil der Menschen ohne japanischen Pass grob?",o:["etwa 2–3 %","etwa 20 %","unter 0,1 %"],c:0},{q:"Wie positioniert sich Japan offiziell?",o:["nicht als Einwanderungsland","als klassisches Einwanderungsland","als abgeschottet ohne Zuwanderung"],c:0}]},{id:"div-5",chapter:"Vielfalt & Minderheiten",title:"Geschlechterrollen im Wandel",facts:[["Recht","Die Verfassung von 1947 garantiert die Gleichberechtigung; ein Gleichstellungsgesetz für den Arbeitsplatz kam 1986."],["Realität","Japan schneidet im Gender-Gap-Index vor allem bei politischer Teilhabe und Führungspositionen schlecht ab; der Lohnabstand ist einer der größten der OECD."],["Namensrecht","Ehepaare müssen sich per Gesetz auf einen gemeinsamen Nachnamen einigen — praktisch nehmen fast immer Frauen den des Mannes an; eine Reform ist umstritten."],["Wandel","Frauenerwerbstätigkeit ist heute hoch, oft aber in Teilzeit; Elternzeit für Väter wird politisch gefördert und langsam mehr genutzt."]],quiz:[{q:"Was schreibt das japanische Namensrecht Ehepaaren vor?",o:["einen gemeinsamen Nachnamen","getrennte Namen","einen neuen Fantasienamen"],c:0},{q:"Wo schneidet Japan im Gender-Gap-Index besonders schwach ab?",o:["politische Teilhabe und Führungspositionen","Alphabetisierung","Lebenserwartung"],c:0},{q:"Wann kam das Gleichstellungsgesetz für den Arbeitsplatz?",o:["1986","1947","2015"],c:0}]},{id:"div-6",chapter:"Vielfalt & Minderheiten",title:"LGBTQ+ in Japan",facts:[["Rechtslage",'Gleichgeschlechtliche Ehe ist landesweit nicht anerkannt; mehrere Gerichte nannten das seit 2021 verfassungswidrig bzw. „im verfassungswidrigen Zustand".'],["Partnerschafts-Zertifikate","Seit 2015 (Shibuya, Setagaya) bieten immer mehr Kommunen Partnerschafts-Bescheinigungen an; sie decken heute einen Großteil der Bevölkerung ab, sind aber rechtlich schwächer als eine Ehe."],["Gesellschaft","Umfragen zeigen wachsende Zustimmung, besonders bei Jüngeren; zugleich ist Sichtbarkeit am Arbeitsplatz oft gering."],["Kultur","Es gibt eine lange Geschichte gleichgeschlechtlicher Motive in Literatur und Theater; Viertel wie Shinjuku Ni-chōme in Tōkyō sind bekannte Zentren."]],quiz:[{q:"Ist die gleichgeschlechtliche Ehe in Japan landesweit anerkannt?",o:["nein","ja, seit 2015","ja, seit 1947"],c:0},{q:"Was bieten viele Kommunen seit 2015 an?",o:["Partnerschafts-Bescheinigungen","volle Eheschließung","Steuerbefreiung"],c:0},{q:"Welches Viertel gilt als LGBTQ+-Zentrum Tōkyōs?",o:["Shinjuku Ni-chōme","Ginza","Akihabara"],c:0}]},{id:"sys-1",chapter:"Alltag & Systeme",title:"Bahn & Nahverkehr als Lebensader",facts:[["JR & Private","Nach der Privatisierung 1987 teilen sich die JR-Gesellschaften und zahlreiche Privatbahnen das Netz; in Ballungsräumen fahren Züge im Minutentakt."],["Pünktlichkeit",'Verspätungen von wenigen Minuten werden angesagt und mit „Verspätungsbescheinigungen" für Arbeitgeber quittiert.'],["Etikette","Leises Verhalten, Handys auf lautlos, Anstellen in Reihen, Priority-Sitze für Ältere, Schwangere und Menschen mit Behinderung."],["Rush Hour",'Auf den stärksten Strecken Tōkyōs liegt die Auslastung morgens deutlich über 100 %; „Oshiya" (Einschieber) sind heute selten, aber legendär.']],quiz:[{q:"Was geschah 1987 mit der Staatsbahn?",o:["Privatisierung in die JR-Gruppe","Verstaatlichung","Stilllegung"],c:0},{q:'Wofür gibt es „Verspätungsbescheinigungen"?',o:["zur Vorlage beim Arbeitgeber","für eine Rückerstattung des Grundpreises","für Touristen"],c:0},{q:"Was gilt in Zügen als üblich?",o:["leises Verhalten, Handy lautlos","Telefonieren am Fenster","Essen warmer Speisen"],c:0}]},{id:"sys-2",chapter:"Alltag & Systeme",title:"Das Gesundheitssystem",facts:[["Pflichtversicherung","Seit 1961 gilt eine allgemeine Krankenversicherungspflicht; Beschäftigte über den Betrieb, andere über die kommunale Versicherung."],["Selbstbeteiligung","Patienten zahlen in der Regel 30 % der Kosten selbst (weniger für Kinder und Ältere); Preise sind landesweit staatlich festgelegt."],["Zugang","Man kann Fachärzte meist direkt aufsuchen; große Kliniken verlangen ohne Überweisung einen Zusatzbeitrag."],["Kennzahlen","Japan hat eine der höchsten Lebenserwartungen der Welt, viele Krankenhausbetten und vergleichsweise häufige Arztkontakte."]],quiz:[{q:"Wie hoch ist die übliche Selbstbeteiligung?",o:["etwa 30 %","0 %","90 %"],c:0},{q:"Seit wann gilt die Versicherungspflicht?",o:["1961","1990","2004"],c:0},{q:"Wie ist der Zugang zu Fachärzten?",o:["meist direkt möglich","nur mit Überweisung erlaubt","nur privat"],c:0}]},{id:"sys-3",chapter:"Alltag & Systeme",title:"Justiz, Polizei und das kōban",facts:[["Kōban","Kleine Polizeiposten (kōban) in den Vierteln sind Anlaufstelle für Wegauskunft, Fundsachen und Nachbarschaftskontakt — ein Modell, das andere Länder übernommen haben."],["Fundsachen","Verlorene Gegenstände und Bargeld werden auffällig oft abgegeben und zurückgegeben; es gibt dafür ein eigenes Gesetz."],["Strafverfahren","Verdächtige können bis zu 23 Tage vor Anklage festgehalten werden; die Verurteilungsquote nach Anklage ist sehr hoch — Kritikpunkte von Menschenrechtsgruppen."],["Laienrichter",'Seit 2009 entscheiden bei schweren Straftaten „saiban-in" (Laienrichter) gemeinsam mit Berufsrichtern.']],quiz:[{q:'Was ist ein „kōban"?',o:["ein kleiner Polizeiposten im Viertel","ein Gericht","ein Ausweis"],c:0},{q:"Was wurde 2009 eingeführt?",o:["Laienrichter (saiban-in)","die Todesstrafe","Videoüberwachung"],c:0},{q:"Was kritisieren Menschenrechtsgruppen?",o:["lange Untersuchungshaft vor Anklage","zu milde Urteile","fehlende Polizei"],c:0}]},{id:"sys-4",chapter:"Alltag & Systeme",title:"Wohnen & Immobilienmarkt",facts:[["Mietkosten",'Beim Einzug fallen oft Kaution (shikikin), „Schlüsselgeld" (reikin, geschenkt an den Vermieter), Maklergebühr und ein Bürge (hoshōnin) an.'],["Baukultur","Wohnhäuser verlieren rechnerisch nach ~20–30 Jahren fast ihren Gebäudewert; Abriss und Neubau sind üblich, auch wegen Erdbebennormen."],["Leerstand","Landesweit stehen Millionen Häuser leer (akiya), vor allem in schrumpfenden ländlichen Regionen; Kommunen vermitteln sie teils sehr günstig."],["Größe",'Stadtwohnungen sind oft kompakt; Raumgrößen werden in „Jō" (Tatami-Matten) angegeben, Küche/Zimmer-Zahl als 1K, 2DK, 3LDK.']],quiz:[{q:'Was ist „reikin"?',o:["einmaliges Schlüsselgeld an den Vermieter","die Kaution","die Monatsmiete"],c:0},{q:'Was bezeichnet „akiya"?',o:["leerstehende Häuser","Neubauten","Ferienwohnungen"],c:0},{q:"Worin wird die Zimmergröße oft angegeben?",o:["in Jō (Tatami-Matten)","in Quadratmeilen","in Schritten"],c:0}]}];export{e as JAPAN};
